import { supabaseFetch } from "./_lib/supabase.js";

const RECIPES = [{"title": "Toshkent To'y Palovi", "category": "Asosiy taom", "cook_time_minutes": 90, "difficulty": "murakkab", "description": "Toshkent shahrining eng mashhur to'y va marosim palovi. Lazer guruchi, no'xat, mayiz va qazi bilan boyitilgan haqiqiy milliy shohona taom.", "ingredients": "[{\"name\": \"Guruch (1kg)\"}, {\"name\": \"Qo'y go'shti (800g)\"}, {\"name\": \"Mol go'shti (200g)\"}, {\"name\": \"Paxta yog'i (200ml)\"}, {\"name\": \"Sariq sabzi (1kg)\"}, {\"name\": \"Piyoz (200g)\"}, {\"name\": \"No'xat (100g)\"}, {\"name\": \"Sarimsoq\"}, {\"name\": \"Zira\"}, {\"name\": \"Mayiz\"}, {\"name\": \"Qazi va Bedana tuxumlari.\"}]", "steps": "[{\"text\": \"Guruchni 5-6 marta kraxmali ketguncha yuving va 35°C iliq sho'r suvda 1 soat ivitib qo'ying.\"}, {\"text\": \"Qozonda paxta yog'ini tutun chiqquncha qizdirib, katta go'sht bo'laklarini solib to'q qizil qobiq bo'lguncha qovuring.\"}, {\"text\": \"Piyoz va somoncha to'g'ralgan sariq sabzini solib yumshaguncha qovuring.\"}, {\"text\": \"Zirvak uchun tuz, zira, ivitilgan no'xat, mayiz va sarimsoq solib, suv quying va past olovda 45 daqiqa qaynating.\"}, {\"text\": \"Guruchni yotqizib baland olovda suvini torttiring, so'ng tayoqcha bilan teshiklar qilib, 25 daqiqa past olovda dimlang.\"}, {\"text\": \"Laganga suzib, ustini to'g'ralgan go'sht, qazi va bedana tuxumlari bilan bezating.\"}]", "is_published": true}, {"title": "Samarqand Oshi Sofi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 105, "difficulty": "murakkab", "description": "Masalliqlari strictly qatlamlarda pishiriladigan va aralashtirmasdan suziladigan afsonaviy Samarqand sofi palovi.", "ingredients": "[{\"name\": \"Basmati/Alanga guruchi (800g)\"}, {\"name\": \"Mol go'shti (800g)\"}, {\"name\": \"Sariyog' (150ml)\"}, {\"name\": \"Piyoz (300g)\"}, {\"name\": \"Sabzi (800g)\"}, {\"name\": \"No'xat\"}, {\"name\": \"Mayiz\"}, {\"name\": \"Sarimsoq va Zira.\"}]", "steps": "[{\"text\": \"Guruchni yuving va iliq sho'r suvda 2 soat iviting.\"}, {\"text\": \"Qozonda sariyog'da katta mol go'shti bo'laklarini va piyozni qovuring, ozgina suv qup 1 soat dimlang.\"}, {\"text\": \"Go'sht ustiga somoncha sabzi, zira, no'xat va mayizni qatlam qilib salang (aralashtirmang!).\"}, {\"text\": \"Ustidan ivigan guruchni yotqizib, sho'r suv quying va baland olovda qaynatib suvini torttiring.\"}, {\"text\": \"20 daqiqa dimlang. Laganga avval guruch, so'ng sabzi va eng tepasiga yumshoq go'shtlarni suzing.\"}]", "is_published": true}, {"title": "Farg'ona Devzira Palovi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 110, "difficulty": "murakkab", "description": "Farg'ona vodiysining qizil Devzira guruchidan tayyorlanadigan achchiq va to'q rangli o'ziga xos to'yimli palov.", "ingredients": "[{\"name\": \"Devzira guruchi (900g)\"}, {\"name\": \"Qo'y go'shti va qovurg'asi (750g)\"}, {\"name\": \"Dumba yog'i va paxta yog'i (250ml)\"}, {\"name\": \"Qizil sabzi (900g)\"}, {\"name\": \"Piyoz (600g)\"}, {\"name\": \"Qizil achchiq qalampir va sarimsoq.\"}]", "steps": "[{\"text\": \"Devzira guruchini 6-7 marta yaxshilab yuvib, sho'r suvda 1 soat iviting.\"}, {\"text\": \"Qozonda dumba yog'i va paxta yog'ida piyozni to'q tillarang bo'lguncha, so'ng go'shtni 20 daqiqa qovuring.\"}, {\"text\": \"Sabzini solib 10 daqiqa qovurib, suv, butun qalampir va sarimsoq solib zirvakni 1 soat sekin qaynating.\"}, {\"text\": \"Guruchni solib baland olovda jadal qaynatib suvini torttiring va 25 daqiqa past olovda dimlang.\"}]", "is_published": true}, {"title": "Buxoro Baxsh Palovi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Buxoro shahrining afsonaviy 'yashil palovi'. Ko'p miqdordagi yangi kashnich va shivit bilan go'sht va jigar mayda to'g'ralib pishiriladi.", "ingredients": "[{\"name\": \"Dumaloq guruch (400g)\"}, {\"name\": \"Mol jigari (250g)\"}, {\"name\": \"Mol go'shti (250g)\"}, {\"name\": \"Kashnich va shivit (4 dasta)\"}, {\"name\": \"Piyoz (2 dona)\"}, {\"name\": \"O'simlik yog'i (60ml)\"}, {\"name\": \"Tuz va murch.\"}]", "steps": "[{\"text\": \"Jigar va go'shtni mayda (0.5cm) kubik qilib qo'lda to'g'rang. Kashnich va shivitni juda nozik to'g'rang.\"}, {\"text\": \"Yog'da piyozni, so'ng go'sht va jigarni 8 daqiqa qovuring.\"}, {\"text\": \"To'g'ralgan ko'katlarni solib aralashtiring va ustidan yuvilgan guruch bilan issiq suv quying.\"}, {\"text\": \"Baland olovda suvini torttirgach, qopqog'ini yopib 25-30 daqiqa sekin olovda dimlang va aralashtirib suzing.\"}]", "is_published": true}, {"title": "Xiva Shivit Oshi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 90, "difficulty": "murakkab", "description": "Xorazm va Xiva shahrining yorqin yashil shivitli ugrasi va go'shtli vaju qaylasi bilan suziladigan mashhur taomi.", "ingredients": "[{\"name\": \"Un (300g)\"}, {\"name\": \"Yangi shivit (100g)\"}, {\"name\": \"Tuxum (1 dona)\"}, {\"name\": \"Mol go'shti (500g)\"}, {\"name\": \"Sabzi\"}, {\"name\": \"Kartoshka\"}, {\"name\": \"Bulg'or qalampiri\"}, {\"name\": \"Sariyog' va Suzma / Qatiq.\"}]", "steps": "[{\"text\": \"Shivitni blenderda pyure qilib, un va tuxum bilan qattiq yashil xamir qoring va 1 soat tindiring.\"}, {\"text\": \"Go'sht, piyoz, sabzi, bulg'or qalampiri va kartoshkadan quyuq 'Vaju' qaylasini tayyorlang.\"}, {\"text\": \"Yashil xamirni 1mm yupqalikda yoyib ugra kesing va qaynoq suvda 2-3 daqiqa qaynatib chaying.\"}, {\"text\": \"Sovuq yashil ugralar ustidan issiq vaju qaylasini quying va sarimsoqli suzma bilan torting.\"}]", "is_published": true}, {"title": "Xorazm Tuxum Baraki", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 60, "difficulty": "murakkab", "description": "Xorazmning betakror mahorat taomi. Yupqa xamir zarflari ichiga suyuq tuxum va sariyog' aralashmasi quyilib qaynatiladi.", "ingredients": "[{\"name\": \"Un (250g)\"}, {\"name\": \"Tuxum (5 dona)\"}, {\"name\": \"Sariyog' (70g)\"}, {\"name\": \"Sut (75ml)\"}, {\"name\": \"Ko'k piyoz\"}, {\"name\": \"Tuz va Qatiq.\"}]", "steps": "[{\"text\": \"Un, suv va tuxumdan o'ta qattiq xamir qorib 30 daqiqa tindiring.\"}, {\"text\": \"Tuxumlarni sariyog', sut, ko'k piyoz va tuz bilan ko'pirtirib suyuq ichlik tayyorlang.\"}, {\"text\": \"Xamirni yupqa yoyib yumaloq kesing va yarim oy shaklida chetini yopishtirib, teshik qoldiring.\"}, {\"text\": \"Teshikdan suyuq tuxumni quying, tezda yopishtiring va zudlik bilan qaynoq sho'r suvga tashlab 3-4 daqiqa pishiring.\"}]", "is_published": true}, {"title": "O'zbek Chuchvarasi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Boy, xushbo'y go'sht bulyonida qaynatib pishiriladigan mitti go'shtli pelmenilar (chuchvara).", "ingredients": "[{\"name\": \"Un (400g)\"}, {\"name\": \"Qiyma (300g)\"}, {\"name\": \"Piyoz (300g)\"}, {\"name\": \"Tuxum (1 dona)\"}, {\"name\": \"Tomat pastasi\"}, {\"name\": \"Sarimsoq\"}, {\"name\": \"Qatiq va ko'katlar.\"}]", "steps": "[{\"text\": \"Un, tuxum va suvdan qattiq xamir qorib 40 daqiqa tindiring.\"}, {\"text\": \"Qiymaga mayda to'g'ralgan piyoz, tuz va murch qo'shib aralashtiring.\"}, {\"text\": \"Xamirni 1.5mm yoyib 4x4 cm mitti kvadratlar kesing, qiyma solib mitti tugunlar tuging.\"}, {\"text\": \"Tomatli sho'r bulyonda chuchvaralarni 5-7 daqiqa qaynatib, bulyoni va qatiq bilan birga suzing.\"}]", "is_published": true}, {"title": "Go'shtli O'zbek Mantisi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 80, "difficulty": "o'rtacha", "description": "Mantiqozon bug'ida pishiriladigan, ichi sershira qo'lda to'g'ralgan go'sht va dumba yog'li klassik o'zbek mantisi.", "ingredients": "[{\"name\": \"Un (500g)\"}, {\"name\": \"Go'sht (600g)\"}, {\"name\": \"Dumba yog'i (150g)\"}, {\"name\": \"Piyoz (600g)\"}, {\"name\": \"Zira\"}, {\"name\": \"Tuxum\"}, {\"name\": \"Qatiq yoki Smetana.\"}]", "steps": "[{\"text\": \"Un, tuxum va suvdan qattiq xamir qorib 30 daqiqa tindiring.\"}, {\"text\": \"Go'sht, dumba yog'i va piyozni qo'lda mayda kubik qilib to'g'rang, zira va murch qo'shing.\"}, {\"text\": \"Xamirni 2mm yoyib 12x12 cm kvadratlar kesing va qiyma hamda dumba bo'lagi solib tuging.\"}, {\"text\": \"Mantiqozon laganlarini moylab, mantilarni 35-40 daqiqa jadal bug'da pishiring.\"}]", "is_published": true}, {"title": "Kartoshkali Xonim (Orama)", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Yupqa yoyilgan xamir ichiga mayda somoncha kartoshka va piyoz solinib bug'da pishiriladigan to'yimli rulon taom.", "ingredients": "[{\"name\": \"Un (400g)\"}, {\"name\": \"Kartoshka (500g)\"}, {\"name\": \"Piyoz (400g)\"}, {\"name\": \"O'simlik yog'i\"}, {\"name\": \"Pomidor pastasi\"}, {\"name\": \"Zira\"}, {\"name\": \"Murch.\"}]", "steps": "[{\"text\": \"Un va suvdan xamir qoring. Kartoshka va piyozni ingichka somoncha to'g'rab, zira soling.\"}, {\"text\": \"Xamirni juda yupqa yoyib yog'lang va kartoshkali aralashmani tekis soling.\"}, {\"text\": \"Xamirni uzun rulon shaklida o'rab, moylangan kaskanda 40 daqiqa bug'da pishiring.\"}, {\"text\": \"Bo'laklarga bo'lib, ustidan achchiq pomidorli sous quying.\"}]", "is_published": true}, {"title": "O'zbek Mastavasi", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 65, "difficulty": "o'rtacha", "description": "Xushbo'y sabzavotlar, qovurilgan go'sht, guruch va kartoshkadan tayyorlanadigan 'suyuq palov' hisoblangan to'yimli sho'rva.", "ingredients": "[{\"name\": \"Go'sht (400g)\"}, {\"name\": \"Guruch (100g)\"}, {\"name\": \"Kartoshka (250g)\"}, {\"name\": \"Sabzi (200g)\"}, {\"name\": \"Piyoz (200g)\"}, {\"name\": \"Tomat pastasi\"}, {\"name\": \"Zira\"}, {\"name\": \"Qatiq va ko'katlar.\"}]", "steps": "[{\"text\": \"Go'sht va piyozni qozonda qovurib, tomat va bulg'or qalampirini qo'shing.\"}, {\"text\": \"Kubik sabzi va kartoshkalarni solib, suv quying va 20 daqiqa qaynating.\"}, {\"text\": \"Ivitilgan guruchni solib guruch pishguncha 15 daqiqa qaynating.\"}, {\"text\": \"Kosalarga suzib, qatiq va ko'katlar sepib torting.\"}]", "is_published": true}, {"title": "Qaynatma Sho'rva", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 135, "difficulty": "o'rtacha", "description": "Suyakli qo'y go'shti, sabzi va butun kartoshkalardan past olovda uzoq vaqt qaynatib pishiriladigan shifobaxsh tiniq sho'rva.", "ingredients": "[{\"name\": \"Suyakli qo'y go'shti (1kg)\"}, {\"name\": \"Piyoz (3 dona)\"}, {\"name\": \"Sabzi (3 dona)\"}, {\"name\": \"Kartoshka (4 dona)\"}, {\"name\": \"Pomidor\"}, {\"name\": \"Bulg'or qalampiri\"}, {\"name\": \"Zira.\"}]", "steps": "[{\"text\": \"Go'shtni sovuq suvga solib qaynating va ko'pigini (kafini) to'liq tozalab oling.\"}, {\"text\": \"Piyoz, butun sabzi va pomidor solib eng past olovda 1 soat mildirating.\"}, {\"text\": \"Tuz va butun kartoshkalarni solib yana 30-40 daqiqa qaynatib pishiring.\"}, {\"text\": \"Go'sht va sabzavotlarni alohida suzib, bulyonni ko'katlar bilan kosalarda torting.\"}]", "is_published": true}, {"title": "An'anaviy Go'shtli Dimlama", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 120, "difficulty": "o'rtacha", "description": "Go'sht, kartoshka, sabzi va karam barglari qozonga qatlam qilib terilib, o'z sharbatida sekin bug'lab pishiriladigan shohona taom.", "ingredients": "[{\"name\": \"Qo'y/Mol qovurg'asi (800g)\"}, {\"name\": \"Karam (1 dona)\"}, {\"name\": \"Kartoshka (6 dona)\"}, {\"name\": \"Sabzi (3 dona)\"}, {\"name\": \"Piyoz (3 dona)\"}, {\"name\": \"Pomidor va Zira.\"}]", "steps": "[{\"text\": \"Qozon tubiga yog' va qovurg'alarni tering, tuz va zira seping.\"}, {\"text\": \"Ustidan piyoz, pomidor, qalampir, sabzi va kartoshkani qatlam qilib zich tering.\"}, {\"text\": \"Eng tepasiga karam barglarini gumbaz qilib yoping va qozon qopqog'ini sochiq bilan mahkam yoping.\"}, {\"text\": \"Past olovda 1.5-2 soat sekin o'z sharbatida dimlang.\"}]", "is_published": true}, {"title": "Qozon Kabob", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 80, "difficulty": "o'rtacha", "description": "Qarsildoq qilib qovurilgan butun kartoshka va yumshoq qo'y qovurg'alaridan tayyorlanadigan mashhur qozon taomi.", "ingredients": "[{\"name\": \"Qo'y qovurg'asi (1kg)\"}, {\"name\": \"Butun kartoshka (800g)\"}, {\"name\": \"O'simlik yog'i (250ml)\"}, {\"name\": \"Zira\"}, {\"name\": \"Koriandr\"}, {\"name\": \"Sirkali piyoz.\"}]", "steps": "[{\"text\": \"Qovurg'alarni zira, murch va tuz bilan 30 daqiqa marinadlang.\"}, {\"text\": \"Qozondagi qizigan yog'da kartoshkalarni qarsildoq qobiq bo'lguncha qovurib oling.\"}, {\"text\": \"Go'shtlarni qizigan yog'da har bir burchagini qizartirib qovuring.\"}, {\"text\": \"Qozon tubiga kartoshka va ustidan go'shtni terib, 100ml suv quying va past olovda 50 daqiqa dimlang.\"}]", "is_published": true}, {"title": "Qo'y Go'shtidan Shashlik", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Mangal ko'mirida tutuntirib pishiriladigan sershira lahm go'sht va dumba yog'li o'zbek shashligi.", "ingredients": "[{\"name\": \"Qo'y go'shti (800g)\"}, {\"name\": \"Dumba yog'i (200g)\"}, {\"name\": \"Piyoz (3 dona)\"}, {\"name\": \"Zira\"}, {\"name\": \"Koriandr\"}, {\"name\": \"Sirka va Mineral suv.\"}]", "steps": "[{\"text\": \"Go'sht va dumbani 3cm kubik qilib to'g'rang.\"}, {\"text\": \"Piyoz suvi, zira, koriandr va mineral suv bilan 4 soat salqinda marinadlang.\"}, {\"text\": \"Sikhga 3 dona go'sht va 1 dona dumba yog'ini tering.\"}, {\"text\": \"Mangal ko'mirida tez-tez buraverib 10-12 daqiqa qizartirib pishiring.\"}]", "is_published": true}, {"title": "Tandir Somsa", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 85, "difficulty": "murakkab", "description": "Qat-qat yumshoq xamir ichida sershira qo'lda to'g'ralgan go'sht va dumba yog'li mashhur o'zbek somsa.", "ingredients": "[{\"name\": \"Un (500g)\"}, {\"name\": \"Sariyog' (150g)\"}, {\"name\": \"Go'sht (400g)\"}, {\"name\": \"Dumba yog'i (100g)\"}, {\"name\": \"Piyoz (500g)\"}, {\"name\": \"Zira va Susan.\"}]", "steps": "[{\"text\": \"Un va iliq suvdan xamir qorib, yupqa yoyib sariyog' surtib qat-qat rulon qiling va sovuting.\"}, {\"text\": \"Go'sht, dumba va piyozni qo'lda mayda to'g'rab zira soling.\"}, {\"text\": \"Xamir bo'laklarini yoyib filling soling va uchburchak tuging.\"}, {\"text\": \"200°C pechda yoki tandirda 35-40 daqiqa qizarguncha pishiring.\"}]", "is_published": true}, {"title": "Toshkent Salati", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Qaynatilgan mol tili somonchasi, Marg'ilon yashil turpi va qarsildoq qovurilgan piyozli mashhur retro salat.", "ingredients": "[{\"name\": \"Mol tili yoki go'shti (300g)\"}, {\"name\": \"Marg'ilon yashil turpi (300g)\"}, {\"name\": \"Piyoz (2 dona)\"}, {\"name\": \"Mayonez (100g)\"}, {\"name\": \"Qaynatilgan tuxum (3 dona).\"}]", "steps": "[{\"text\": \"Turpni somoncha to'g'rab 15 daqiqa muzdek sho'r suvda achchig'ini chiqaring va quriting.\"}, {\"text\": \"Qaynatilgan mol tili va tuxumlarni uzunchoq somoncha to'g'rang.\"}, {\"text\": \"Piyoz halqalarini unga bulab yog'da qarsildoq bo'lguncha qovuring.\"}, {\"text\": \"Masalliqlarni mayonez bilan aralashtirib, ustini qarsildoq piyoz bilan bezating.\"}]", "is_published": true}, {"title": "Achichuk Salati", "category": "Salatlar & Gazaklar", "cook_time_minutes": 10, "difficulty": "oson", "description": "Palov va shashliklarning ajralmas, nordon-shirin yangi pomidor va yupqa piyozli milliy salat.", "ingredients": "[{\"name\": \"Qizil shirin pomidor (4 dona)\"}, {\"name\": \"Piyoz (1 dona)\"}, {\"name\": \"Tuz\"}, {\"name\": \"Shivit yoki kashnich va Achchiq qalampir.\"}]", "steps": "[{\"text\": \"Piyozni shaffof yupqalikda halqa qilib to'g'rab muzdek suvda chaying.\"}, {\"text\": \"Shirin pomidorlarni pichoqda yupqa parrak qilib kesing.\"}, {\"text\": \"Piyoz, pomidor va ko'katlarni birlashtirib, faqat tortishdan oldin tuz seping.\"}]", "is_published": true}, {"title": "Asalli \"Medovik\" Torti", "category": "Milliy Quyuq Taomlar", "cook_time_minutes": 105, "difficulty": "murakkab", "description": "8-10 qavatli yupqa asalli biskvit va smetanali mayin kremdan tayyorlanadigan og'izda eriydigan shirinlik.", "ingredients": "[{\"name\": \"Un (450g)\"}, {\"name\": \"Tabiiy asal (140g)\"}, {\"name\": \"Shakar (100g)\"}, {\"name\": \"Sariyog' (85g)\"}, {\"name\": \"Tuxum (3 dona)\"}, {\"name\": \"Soda (6g)\"}, {\"name\": \"Smetana va Qaymoq (850g).\"}]", "steps": "[{\"text\": \"Bug' hammomida sariyog', shakar va asalni eritib, soda solib 3 barobar ko'pirtiring.\"}, {\"text\": \"Tuxum va un qo'shib xamir qoring, 8 bo'lakka bo'lib yupqa yoying va pechda 5 daqiqadan pishiring.\"}, {\"text\": \"Smetana, qaymoq va shakar upasidan yengil krem tayyorlang.\"}, {\"text\": \"Qavatlarga krem surtib yig'ing va muzlatgichda 10 soatga tindiring.\"}]", "is_published": true}, {"title": "Turkiya Baqlavasi (Baklava)", "category": "Turk Oshxonasi", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Turkiyaning Gaziantep viloyatining mashhur milliy deserti. Yupqa filo xamiri, saryog' va yong'oq/pista qatlamlaridan sovuq qiyom bilan tayyorlanadi.", "ingredients": "[{\"name\": \"Filo xamiri (yufka)\"}, {\"name\": \"Saryog'\"}, {\"name\": \"Yong'oq yoki pista\"}, {\"name\": \"Shakar\"}, {\"name\": \"Suv\"}, {\"name\": \"Limon sharbati\"}]", "steps": "[{\"text\": \"Qiyom (sirop) tayyorlash: Suv, shakar va limon sharbatini 10-15 daqiqa qaynatib, sovitishga qo'ying.\"}, {\"text\": \"Filo xamiri varaqlariga eritilgan saryog' surtib, ketma-ket qatlamlab taxlang.\"}, {\"text\": \"Har bir necha qatlam orasiga maydalangan yong'oq yoki pista seping.\"}, {\"text\": \"Pishirishdan oldin romb yoki kvadrat shaklida kesib, ustiga qolgan eritilgan saryog'ni tekis quying.\"}, {\"text\": \"180°C ga qizdirilgan pechda oltin-zarhal rangga kirguncha (35-45 daqiqa) pishiring.\"}, {\"text\": \"Pechdan chiqqan issiq baqlava ustiga sovuq qiyomni quying va 2-4 soat shimilishi uchun qoldiring.\"}]", "is_published": true}, {"title": "Turk Loqumi (Turkish Delight)", "category": "Turk Oshxonasi", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Usmonli imperiyasidan yetib kelgan mashhur qandolat deserti. Shakar, kraxmal va xushbo'y sharbatlardan tayyorlanadi.", "ingredients": "[{\"name\": \"Shakar\"}, {\"name\": \"Suv\"}, {\"name\": \"Makkajo'xori kraxmali\"}, {\"name\": \"Limon sharbati\"}, {\"name\": \"Gul suvi yoki limon essensiyasi\"}, {\"name\": \"Shakar kukuni\"}]", "steps": "[{\"text\": \"Shakar va suvdan quyuq shirin sirop tayyorlang.\"}, {\"text\": \"Kraxmalni alohida sovuq suvda tekis eritib oling.\"}, {\"text\": \"Kraxmalli aralashmani siropga qo'shib, past olovda to'xtovsiz aralashtirib quyuqlashtiring.\"}, {\"text\": \"Xushbo'ylik beruvchi gul suvi yoki limon essensiyasini me'yorida qo'shing.\"}, {\"text\": \"Aralashmani to'rtburchak qolipga quyib, to'liq qotguncha xona haroratida qoldiring.\"}, {\"text\": \"Qotgach, kub shaklida kesib, shakar kukuniga botirib oling.\"}]", "is_published": true}, {"title": "Turkcha Sütlaç (Sutli Desert)", "category": "Turk Oshxonasi", "cook_time_minutes": 40, "difficulty": "oson", "description": "Sut, guruch va vanillin qo'shib pishiriladigan va pechda usti qizartiriladigan turkcha sutli pudding deserti.", "ingredients": "[{\"name\": \"Sut\"}, {\"name\": \"Guruch\"}, {\"name\": \"Shakar\"}, {\"name\": \"Guruch uni yoki kraxmal\"}, {\"name\": \"Vanillin\"}, {\"name\": \"Dolchin\"}]", "steps": "[{\"text\": \"Guruchni suvda yumshaguncha qaynatib oling.\"}, {\"text\": \"Sutni qo'shib, past olovda sekin qaynating.\"}, {\"text\": \"Shakar va ozgina suvda eritilgan quyuqlashtiruvchini (kraxmal/guruch uni) qo'shing.\"}, {\"text\": \"Aralashma quyuqlashgach, maxsus idishlarga quying.\"}, {\"text\": \"Xohishga ko'ra, ustini pechda 200°C da qizartirib oling (Fırın Sütlaç).\"}, {\"text\": \"Sovutib, ustiga dolchin sepgan holda xizmat qiling.\"}]", "is_published": true}, {"title": "Revani (Manna Yarma Keksa)", "category": "Turk Oshxonasi", "cook_time_minutes": 35, "difficulty": "oson", "description": "Usmonli oshxonasidan manna yarmasidan pishirilib, ustidan sharbat (sirop) quyiladigan yumshoq keks.", "ingredients": "[{\"name\": \"Manna yarmasi (manka)\"}, {\"name\": \"Bug'doy uni\"}, {\"name\": \"Tuxum\"}, {\"name\": \"Shakar\"}, {\"name\": \"Qatiq yoki yogurt\"}, {\"name\": \"O'simlik yog'i\"}, {\"name\": \"Razrixlitel\"}, {\"name\": \"Qiyom\"}]", "steps": "[{\"text\": \"Tuxum va shakarni ko'pik bo'lguncha yaxshilab ko'pirtiring.\"}, {\"text\": \"Qatiq, o'simlik yog'i, un va manna yarmasini qo'shing.\"}, {\"text\": \"Qabartma kukunini qo'shib, bir xil massa holiga keltiring.\"}, {\"text\": \"Yog'langan qolipga quyib, pechda pishiring.\"}, {\"text\": \"Pechdan chiqqan issiq keks ustiga sovuq qiyomni quying.\"}, {\"text\": \"Qiyom to'liq shimilgach, bo'laklarga bo'ling.\"}]", "is_published": true}, {"title": "Şekerpare Pechenyesi", "category": "Turk Oshxonasi", "cook_time_minutes": 25, "difficulty": "oson", "description": "Saryog', manna yarmasi va findiq/bodom bilan pechda pishirilib, shirin qiyomga botiriladigan mashhur turk pechenyesi.", "ingredients": "[{\"name\": \"Saryog'\"}, {\"name\": \"Shakar kukuni (pudra)\"}, {\"name\": \"Tuxum\"}, {\"name\": \"Bug'doy uni\"}, {\"name\": \"Manna yarmasi\"}, {\"name\": \"Razrixlitel\"}, {\"name\": \"Qiyom\"}, {\"name\": \"Findiq yoki bodom\"}]", "steps": "[{\"text\": \"Xona haroratidagi saryog' va shakar kukunini aralashtiring.\"}, {\"text\": \"Tuxum, un, manna yarmasi va qabartma kukunini qo'shib yumshoq xamir qoring.\"}, {\"text\": \"Xamirdan kichik dumaloq bo'laklar yasang.\"}, {\"text\": \"Har birining o'rtasiga findiq yoki bodom donasini bosing.\"}, {\"text\": \"Pechda oltin rangga kirguncha pishiring.\"}, {\"text\": \"Pechdan chiqqan issiq pechenyelar ustiga sovuq qiyom quying.\"}]", "is_published": true}, {"title": "Tulumba Tatlısı", "category": "Turk Oshxonasi", "cook_time_minutes": 30, "difficulty": "o'rtacha", "description": "Qaynatilgan xamirdan tishli shaklda yog'da qovurilib, sovuq qiyomda shimitiladigan qarsillama desert.", "ingredients": "[{\"name\": \"Suv\"}, {\"name\": \"Saryog'\"}, {\"name\": \"Bug'doy uni\"}, {\"name\": \"Tuxum\"}, {\"name\": \"Kraxmal\"}, {\"name\": \"Qiyom (sirop)\"}, {\"name\": \"O'simlik yog'i\"}]", "steps": "[{\"text\": \"Suv va saryog'ni qizdirib, un va kraxmal qo'shib qaynatilgan xamir tayyorlang.\"}, {\"text\": \"Xamir biroz sovigach, tuxumlarni birin-ketin qo'shib silliq massa bo'lguncha ko'pirtiring.\"}, {\"text\": \"Qandolat qopidan tishli nasadka orqali uzunchoq shakllar siqib chiqaring.\"}, {\"text\": \"O'rtacha issiqlikdagi yog'da oltin rang bo'lguncha qovuring.\"}, {\"text\": \"Qovurilgan tulumbalarni darhol sovuq qiyomga solib shimitib oling.\"}, {\"text\": \"Xizmat qilishdan oldin ortiqcha qiyomni to'kib tashlang.\"}]", "is_published": true}, {"title": "Turk Künefe Deserti", "category": "Turk Oshxonasi", "cook_time_minutes": 30, "difficulty": "o'rtacha", "description": "Xatay viloyatining tilsimon kadayif xamiri, eruvchan tuzsiz pishloq va saryog'dan pishiriladigan issiq qiyomli desert.", "ingredients": "[{\"name\": \"Kadayif xamiri\"}, {\"name\": \"Tuzsiz eruvchan pishloq (Mozzarella)\"}, {\"name\": \"Saryog'\"}, {\"name\": \"Shakar\"}, {\"name\": \"Suv\"}, {\"name\": \"Limon sharbati\"}, {\"name\": \"Pista\"}]", "steps": "[{\"text\": \"Qiyomni oldindan tayyorlab sovutib qo'ying.\"}, {\"text\": \"Kadayif xamirini eritilgan saryog' bilan yaxshilab aralashtiring.\"}, {\"text\": \"Kadayifning yarmisini maxsus tavaga yoyib, mahkam bosing.\"}, {\"text\": \"O'rtasiga tuzsiz pishloqni tekis qilib joylashtiring.\"}, {\"text\": \"Qolgan kadayifni ustiga yoyib, yana bir bor bosib chiqing.\"}, {\"text\": \"Past olovda tavada ikkala tarafini qizartiring (yoki pechda pishiring).\"}, {\"text\": \"Issiq künefe ustiga sovuq qiyom quying va pista seping.\"}]", "is_published": true}, {"title": "Lokma (Qiyomli Sharchalar)", "category": "Turk Oshxonasi", "cook_time_minutes": 25, "difficulty": "o'rtacha", "description": "Egey dengizi qirg'oqlarining oshgan xamirdan yog'da qovurilib, shirin siropda shimitiladigan mashhur sharchalari.", "ingredients": "[{\"name\": \"Bug'doy uni\"}, {\"name\": \"Xamirturush (drojji)\"}, {\"name\": \"Suv\"}, {\"name\": \"Shakar\"}, {\"name\": \"Tuz\"}, {\"name\": \"O'simlik yog'i\"}, {\"name\": \"Qiyom\"}]", "steps": "[{\"text\": \"Un, suv va xamirturushdan yumshoq xamir qoring va oshishi uchun dam bering.\"}, {\"text\": \"Oshgan xamirdan kichik dumaloq bo'laklar (sharchalar) oling.\"}, {\"text\": \"Qizdirilgan o'simlik yog'ida oltin rang bo'lguncha qovuring.\"}, {\"text\": \"Qovurilgan lokmalarni sovuq qiyomga soling.\"}, {\"text\": \"Bir necha daqiqa qiyomni shimgach, suzib oling.\"}, {\"text\": \"Issiq va yangi holida xizmat qiling.\"}]", "is_published": true}, {"title": "Kazandibi (Karamellangan Sutli Desert)", "category": "Turk Oshxonasi", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Usmonli saroy oshxonasining sutli deserti. Tova tubida qatlam hosil qilib, karamellashtirib pishiriladi.", "ingredients": "[{\"name\": \"Sut\"}, {\"name\": \"Shakar\"}, {\"name\": \"Guruch uni\"}, {\"name\": \"Makkajo'xori kraxmali\"}, {\"name\": \"Sariyog'\"}, {\"name\": \"Vanillin\"}]", "steps": "[{\"text\": \"Sut, shakar, guruch uni va kraxmalni aralashtirib past olovda quyuqlashguncha pishiring.\"}, {\"text\": \"Tova tubiga saryog' surtib, aralashmani qalin qatlam qilib yoying.\"}, {\"text\": \"Pastki qismi karamellashib (jigarrang tusga kirguncha) pishiring.\"}, {\"text\": \"Xona haroratida va muzlatgichda sovuting.\"}, {\"text\": \"Bo'laklab, karamellangan tarafini yuqoriga ag'darib idishga oling.\"}]", "is_published": true}, {"title": "Turkcha Muhallebi Krem Deserti", "category": "Turk Oshxonasi", "cook_time_minutes": 20, "difficulty": "oson", "description": "Sut, shakar, kraxmal va vanillin qo'shib tayyorlanadigan yengil, ipakdek muloyim krem-desert.", "ingredients": "[{\"name\": \"Sut\"}, {\"name\": \"Shakar\"}, {\"name\": \"Makkajo'xori kraxmali\"}, {\"name\": \"Guruch uni\"}, {\"name\": \"Vanillin\"}, {\"name\": \"Sariyog'\"}]", "steps": "[{\"text\": \"Quruq ingredientlarni idishda aralashtiring.\"}, {\"text\": \"Sutni asta-sekin qo'shib, silliq va bir xil massa hosil qiling.\"}, {\"text\": \"Past olovda to'xtovsiz aralashtirib, quyuqlashguncha pishiring.\"}, {\"text\": \"Idishlarga quyib sovuting.\"}, {\"text\": \"Ustiga dolchin yoki maydalangan pista sepib xizmat qiling.\"}]", "is_published": true}, {"title": "İrmik Helvası (Manna Halvosi)", "category": "Turk Oshxonasi", "cook_time_minutes": 30, "difficulty": "oson", "description": "Sariyog'da qovurilgan manna yarmasiga sutli yoki suvli shirin qiyom quyilib tayyorlanadigan turk halvosi.", "ingredients": "[{\"name\": \"Manna yarmasi (manka) yoki kunjut pastasi\"}, {\"name\": \"Sariyog'\"}, {\"name\": \"Shakar\"}, {\"name\": \"Suv yoki sut\"}, {\"name\": \"Yong'oq\"}]", "steps": "[{\"text\": \"Tovada sariyog'ni eritib, manna yarmasini oltin rangga kirguncha qovuring.\"}, {\"text\": \"Alohida idishda shakar va suvni (yoki sutni) eritib iliq qiyom tayyorlang.\"}, {\"text\": \"Qiyomni qovurilgan mannaga asta-sekin, aralashtirgan holda quying.\"}, {\"text\": \"Aralashma quyuqlashib, suyuqlikni to'liq shimguncha pishiring.\"}, {\"text\": \"Olovni o'chirib, 15-20 daqiqa qopqog'i yopiq holda dam bering.\"}]", "is_published": true}, {"title": "Aşure (Nuh Payg'ambar Deserti)", "category": "Turk Oshxonasi", "cook_time_minutes": 90, "difficulty": "o'rtacha", "description": "Bug'doy, no'xat, lobiya, quritilgan mevalar va yong'oqlardan tayyorlanadigan eng qadimiy marosim deserti.", "ingredients": "[{\"name\": \"Bug'doy\"}, {\"name\": \"No'xat\"}, {\"name\": \"Lobiya\"}, {\"name\": \"Quritilgan mevalar (o'rik\"}, {\"name\": \"mayiz)\"}, {\"name\": \"Yong'oq\"}, {\"name\": \"Shakar\"}, {\"name\": \"Suv\"}, {\"name\": \"Anor\"}]", "steps": "[{\"text\": \"Bug'doy, loviya va no'xatni oldindan (bir kecha) ivitib, alohida pishirib oling.\"}, {\"text\": \"Barcha pishgan donli mahsulotlarni katta qozonga solib, suv bilan qaynating.\"}, {\"text\": \"Quritilgan mevalar va shakarni qo'shing.\"}, {\"text\": \"Past olovda aralashma quyuqlashguncha sekin pishiring.\"}, {\"text\": \"Idishlarga quyib, sovugach ustini yong'oq va anor donalari bilan bezang.\"}]", "is_published": true}, {"title": "Pişmaniye (Turk Paxtahalvosi)", "category": "Turk Oshxonasi", "cook_time_minutes": 90, "difficulty": "murakkab", "description": "Izmit shahrining nozik, ip-ip bo'lib ajraladigan paxtahalvosiga o'xshash mashhur milliy qandolati.", "ingredients": "[{\"name\": \"Bug'doy uni\"}, {\"name\": \"Shakar\"}, {\"name\": \"Suv\"}, {\"name\": \"Sariyog'\"}, {\"name\": \"Limon sharbati\"}]", "steps": "[{\"text\": \"Unni saryog'da past olovda hidsizlanguncha qovuring va sovitib qo'ying.\"}, {\"text\": \"Shakar, suv va limon kislotasidan quyuq karamel tayyorlang.\"}, {\"text\": \"Karamelli massani egiluvchan halqa holiga kelguncha sovuting.\"}, {\"text\": \"Karamel halqasini qovurilgan un ustiga qo'yib, cho'zib, bukab va qayta-qayta cho'zib ingichka ip shakliga keltiring.\"}, {\"text\": \"Yupqa ipga aylangan pishmaniyani to'plar shaklida taxlang.\"}]", "is_published": true}, {"title": "Mukammal Pirog Xamiri (Perfect Pie Crust)", "category": "Pishiriqlar & Xamirlar", "cook_time_minutes": 20, "difficulty": "oson", "description": "Muzday saryog' va un birlashmasidan tayyorlanadigan, har qanday shirin va sho'r piroglar uchun eng zo'r va qarsildoq korj xamiri.", "ingredients": "[{\"name\": \"1 ¼ stakan un\"}, {\"name\": \"½ choy qoshiq tuz\"}, {\"name\": \"115 g sovuq saryog' (kubik kesilgan)\"}, {\"name\": \"4–5 osh qoshiq muzday suv.\"}]", "steps": "[{\"text\": \"Un va tuzni aralashtiring.\"}, {\"text\": \"Sovuq saryog'ni qo'shib, uvoq hosil bo'lguncha barmoqlar bilan uvalang.\"}, {\"text\": \"Muzday suvni oz-ozdan quyib, xamirni to'plang.\"}, {\"text\": \"Plyonkaga o'rab, muzlatgichda kamida 1 soat tindiring.\"}]", "is_published": true}, {"title": "Yer-yong'oqli Pechenye (Peanut Butter Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 30, "difficulty": "oson", "description": "Yer-yong'oq pastasi va qovurilgan yer-yong'oq bo'laklari bilan pishiriladigan xushbo'y va og'izda eriydigan pechenye.", "ingredients": "[{\"name\": \"1 stakan yer-yong'oq pastasi (peanut butter)\"}, {\"name\": \"1 stakan shakar\"}, {\"name\": \"1 dona tuxum\"}, {\"name\": \"1 stakan qovurilgan tuzli yer-yong'oq (maydalangan).\"}]", "steps": "[{\"text\": \"Pechni 175°C gacha qizdiring.\"}, {\"text\": \"Yer-yong'oq pastasi, shakar va tuxumni aralashtiring.\"}, {\"text\": \"Maydalangan yer-yong'oqni qo'shing.\"}, {\"text\": \"Xamirdan sharchalar yasab, sanchqi bilan katakcha naqsh qiling.\"}, {\"text\": \"175°C pechda 10–12 daqiqa tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Tovuqli va Kartoshkali Gratin (Chicken and Potato Gratin)", "category": "Quyuq Taomlar", "cook_time_minutes": 75, "difficulty": "o'rtacha", "description": "Saryog'da qizartirilgan qaymoqli sous, kichik kartoshkalar va tovuq go'shtidan pechda pishiriladigan shirin gratin.", "ingredients": "[{\"name\": \"1.3 kg tovuq go'shti (son va boldirlar)\"}, {\"name\": \"450 g kichik kartoshka (ikkiga bo'lingan)\"}, {\"name\": \"250 g sharlot piyoz\"}, {\"name\": \"75 g saryog'\"}, {\"name\": \"180 ml qaymoq (heavy cream)\"}, {\"name\": \"2 tish sarimsoq\"}, {\"name\": \"Tuz\"}, {\"name\": \"murch\"}, {\"name\": \"muskat yong'og'i\"}, {\"name\": \"mavrak va timyan\"}, {\"name\": \"100 g qotgan non uvoqlari.\"}]", "steps": "[{\"text\": \"Tovuqni tuzlab 1 soat tindiring. Pechni 220°C ga qizdiring.\"}, {\"text\": \"Saryog'ni tovada qizartirib brown-butter qiling, qaymoq, sarimsoq va ziravorlar qo'shing.\"}, {\"text\": \"Tovuq go'shtini tovada qizartirib oling.\"}, {\"text\": \"Qolipga tovuq va kartoshkalarni tizib, ustidan qaymoqli sousni quying. 40 daqiqa pechda pishiring.\"}, {\"text\": \"Non uvoqlarini qovurib, pishgan gratin ustidan seping.\"}]", "is_published": true}, {"title": "Chhena Poda — Ziravorli Chizkeyk (Chhena Poda)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Tvorog, kardamon va manka yormasidan karamel qatlam ustida pishiriladigan afsonaviy hindistoncha tvorogli chizkeyk.", "ingredients": "[{\"name\": \"225 g panir (yoki uydagidek tvorog)\"}, {\"name\": \"¼ stakan shakar kukuni\"}, {\"name\": \"½ choy qoshiq hil (kardamon)\"}, {\"name\": \"2 osh qoshiq manny yormasi (manka)\"}, {\"name\": \"2 osh qoshiq eritilgan saryog'\"}, {\"name\": \"¼ stakan sut\"}, {\"name\": \"Kesh'yu va mayiz\"}, {\"name\": \"3 osh qoshiq shakar (karamel uchun).\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Qolip tubida shakarni eritib karamel holiga keltiring.\"}, {\"text\": \"Tvorog, shakar kukuni, hil, manka, saryog' va sutni silliq bo'lguncha aralashtiring.\"}, {\"text\": \"Kesh'yu va mayizni solib, karamelli qolipga quying.\"}, {\"text\": \"175°C pechda 40–45 daqiqa pishiring. Sovugach agdarib dasturxonga torting.\"}]", "is_published": true}, {"title": "Mayin Kartoshka Pyuresi (Our Favorite Creamy Mashed Potatoes)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Issiq sut, smetana, saryog' va sarimsoq aromati bilan ezilgan o'ta yumshoq va mayin klassik kartoshka pyuresi.", "ingredients": "[{\"name\": \"1.8 kg kartoshka (tozalanib\"}, {\"name\": \"bo'lingan)\"}, {\"name\": \"6 tish sarimsoq\"}, {\"name\": \"300 ml sut\"}, {\"name\": \"200 g saryog'\"}, {\"name\": \"100 g smetana\"}, {\"name\": \"Tuz\"}, {\"name\": \"qora murch va timyan.\"}]", "steps": "[{\"text\": \"Kartoshka va sarimsoqni tuzli suvda 20 daqiqa yumshaguncha qaynatib oling.\"}, {\"text\": \"Sut, saryog' va timyanni isitib oling.\"}, {\"text\": \"Kartoshkani suvidan ajratib ezing.\"}, {\"text\": \"Issiq sutli aralashma va smetanani qo'shib silliq krem holatiga keltiring.\"}]", "is_published": true}, {"title": "Karamel-Olmali Kreol Chizkeyki (Creole Apple Cheesecake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 90, "difficulty": "murakkab", "description": "Krekerli korj, yumshoq pishloqli krem hamda ustiga dimlangan karamelli nordon olma qatlami bilan pishiriladigan dabdabali chizkeyk.", "ingredients": "[{\"name\": \"Korj: 2 stakan grek krekeri uvoqlari\"}, {\"name\": \"100 g saryog'\"}, {\"name\": \"3 osh qoshiq shakar. Krem: 900 g cream cheese\"}, {\"name\": \"1.3 stakan smetana\"}, {\"name\": \"1 stakan shakar\"}, {\"name\": \"2 dona tuxum\"}, {\"name\": \"vanil. Ustiga: 7 dona nordon olma\"}, {\"name\": \"50 g saryog'\"}, {\"name\": \"½ stakan jigarrang shakar\"}, {\"name\": \"dolchin va kardamon.\"}]", "steps": "[{\"text\": \"Korj masalliqlarini aralashtirib qolipga presslang va 190°C pechda 10 daqiqa pishiring.\"}, {\"text\": \"Cream cheese va shakarni ko'pirtiring, smetana va tuxumlarni qo'shing. Korjga quyib suvli hammomda (water bath) 175°C pechda 1 soat pishiring.\"}, {\"text\": \"Olmalarni saryog', shakar va ziravorlar bilan tovada yumshaguncha dimlang.\"}, {\"text\": \"Chizkeyk sovugach, olmali karamelni ustiga yoying.\"}]", "is_published": true}, {"title": "Kokosli Sutda Pishirilgan Makkajuxori va Yarma (Coconut Creamed Corn)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 25, "difficulty": "oson", "description": "Zanjabil, zardachub va kokos sutida dimlangan shirin makkajuxori va kinoa donchalari.", "ingredients": "[{\"name\": \"4 so'ta makkajuxori donchalari\"}, {\"name\": \"1 stakan pishirilgan yarma (kinoa yoki farro)\"}, {\"name\": \"1 stakan kokos suti\"}, {\"name\": \"1 dona xalapeno murchi\"}, {\"name\": \"Zanjabil\"}, {\"name\": \"sarimsoq\"}, {\"name\": \"zardachub\"}, {\"name\": \"tuz va laym.\"}]", "steps": "[{\"text\": \"Tovada yog'ni qizdirib zanjabil, sarimsoq va murch pishiring. Zardachub va makkajuxorini qo'shib 5 daqiqa qovuring.\"}, {\"text\": \"Pishgan yarma va kokos sutini qo'shing, 3 daqiqa dimlang.\"}, {\"text\": \"Ustiga qovurilgan piyoz seping va laym bo'lagi bilan torting.\"}]", "is_published": true}, {"title": "Pomidor va Qovurilgan Sarimsoqli Pirog (Tomato & Roasted Garlic Pie)", "category": "Pishiriqlar & Tuzli Piroglar", "cook_time_minutes": 90, "difficulty": "o'rtacha", "description": "Pechda tob berilgan pomidorlar, erigan pishloq va sarimsoqli krem bilan pishiriladigan ajoyib tuzli fransuzcha pirog.", "ingredients": "[{\"name\": \"1.1 kg pomidor bo'laklari\"}, {\"name\": \"6 tish sarimsoq\"}, {\"name\": \"115 g saryog'\"}, {\"name\": \"250 g kreker uvoqlari\"}, {\"name\": \"2 dona tuxum\"}, {\"name\": \"300 g pishloq (Taleggio va Parmezan)\"}, {\"name\": \"½ stakan mayonez\"}, {\"name\": \"timyan va murch.\"}]", "steps": "[{\"text\": \"Pomidorlarni 240°C pechda 25 daqiqa biroz quritib oling.\"}, {\"text\": \"Sarimsoqni saryog'da qovuring. Kreker uvoqlarini tuxum va sarimsoqli saryog' bilan aralashtirib qolipga presslang va 10 daqiqa pishiring.\"}, {\"text\": \"Pishloq, mayonez, ziravorlar va sarimsoqni aralashtiring.\"}, {\"text\": \"Qolipga pishloqli krem va pomidorlarni qatlam qilib tizib, 190°C pechda 1 soat pishiring.\"}]", "is_published": true}, {"title": "Smetana va Piyozli Kartoshka Salati (Sour Cream Potato Salad)", "category": "Salatlar & Gazaklar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Yumshoq kartoshka, smetana, dijon xardali va ustiga uvalangan qarsildoq kartoshka chipslari solingan xushbo'y salat.", "ingredients": "[{\"name\": \"900 g kichik kartoshka\"}, {\"name\": \"1 stakan smetana\"}, {\"name\": \"¼ stakan mayonez\"}, {\"name\": \"1 osh qoshiq piyoz kukuni\"}, {\"name\": \"2 choy qoshiq dijon xardali\"}, {\"name\": \"Yashil piyoz\"}, {\"name\": \"qizil piyoz va sarimsoq\"}, {\"name\": \"Kartoshka chipslari (ustiga uvatish uchun).\"}]", "steps": "[{\"text\": \"Kartoshkani tuzli suvda yumshaguncha qaynatib oling va biroz ezing.\"}, {\"text\": \"Smetana, mayonez, piyoz kukuni, xardal, sarimsoq va yashil piyozni aralashtiring.\"}, {\"text\": \"Kartoshkalarni sousga solib aralashtiring va sovuting.\"}, {\"text\": \"Dasturxonga tortish oldidan ustiga uvalangan chipslarni seping.\"}]", "is_published": true}, {"title": "Muzlatilgan Avokadoli Pirog (Frozen Avocado Cake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 30, "difficulty": "oson", "description": "Yangi avokado, quyultirilgan sut (sgushchenka) va laym sharbatidan tayyorlanadigan tetiklashtiruvchi muzlatilgan pishiriq.", "ingredients": "[{\"name\": \"Korj: 180 g kreker uvoqlari\"}, {\"name\": \"⅓ stakan quyultirilgan sut. Asos: 3 dona avokado\"}, {\"name\": \"450 g cream cheese\"}, {\"name\": \"1.5 banka quyultirilgan sut\"}, {\"name\": \"limon va laym sharbati hamda rendasi.\"}]", "steps": "[{\"text\": \"Kreker va ⅓ stakan quyultirilgan sutni aralashtirib qolipga yoying, 180°C pechda 12 daqiqa pishirib sovuting.\"}, {\"text\": \"Avokado, cream cheese, quyultirilgan sut va limon sharbatini kombaynda silliq ko'pirtiring.\"}, {\"text\": \"Kremni korj ustiga yoyib, kamida 6 soat muzlatgichda muzlating.\"}, {\"text\": \"Kesishdan 15 daqiqa oldin xonaga chiqaring.\"}]", "is_published": true}, {"title": "Shokoladli va Qovoqchali Pirog (Chocolate Zucchini Cake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Kakao, shokolad tomchilari va maydalangan qovoqcha (zucchini) qo'shilgan, jonsizlanmaydigan va sirli darajada shirin keks.", "ingredients": "[{\"name\": \"2 stakan un\"}, {\"name\": \"½ stakan kakao kukuni\"}, {\"name\": \"1 choy qoshiq soda\"}, {\"name\": \"tuz\"}, {\"name\": \"1.5 stakan shakar\"}, {\"name\": \"115 g saryog'\"}, {\"name\": \"½ stakan o'simlik yog'i\"}, {\"name\": \"2 dona tuxum\"}, {\"name\": \"½ stakan qatiq/kefir\"}, {\"name\": \"2 stakan qirg'ichdan chiqarilgan qovoqcha (zucchini)\"}, {\"name\": \"1 stakan shokolad tomchilari va yong'oq.\"}]", "steps": "[{\"text\": \"Quruq va ho'l masalliqlarni alohida idishlarda aralashtiring.\"}, {\"text\": \"Xamirlarni birlashtirib, qirilgan qovoqchani qo'shing.\"}, {\"text\": \"Qolipga quyib, ustidan shokolad va yong'oq seping.\"}, {\"text\": \"165°C pechda 50 daqiqa pishiring.\"}]", "is_published": true}, {"title": "Dakgangjeong — Koreyscha Qarsildoq Tovuq (Dakgangjeong)", "category": "Koreys & Dunyo Oshxonasi", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Kraxmalda ikki marta qovurilgan qarsildoq tovuq bo'laklari va shirin-achchiq asalli asil koreyscha sous.", "ingredients": "[{\"name\": \"1.1 kg tovuq qanotchalari yoki bo'laklari\"}, {\"name\": \"½ stakan kartoshka kraxmali\"}, {\"name\": \"tuz va murch. Sous: ½ stakan asal\"}, {\"name\": \"3 osh qoshiq soyali sous\"}, {\"name\": \"2 osh qoshiq shakar\"}, {\"name\": \"sarimsoq\"}, {\"name\": \"zanjabil va qurutilgan achchiq qalampir. Qovurish uchun o'simlik yog'i\"}, {\"name\": \"kunchut.\"}]", "steps": "[{\"text\": \"Tovuq bo'laklarini tuz, murch va kraxmalga bulab oling.\"}, {\"text\": \"Yog'da ikki marta (qarsildoq bo'lguncha) qovurib oling.\"}, {\"text\": \"Tovada sous masalliqlarini 2–3 daqiqa qaynatib quyultiring.\"}, {\"text\": \"Qovurilgan tovuqlarni sousga solib aralashtiring va kunchut seping.\"}]", "is_published": true}, {"title": "Bodomli Korjda Yangi Mevali Tart (Fresh Fruit Tart)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Bodom unli qarsildoq tart korji, ipakdek mayin zavarnoy krem va ustida yangi rezavor mevalar.", "ingredients": "[{\"name\": \"Korj: 1 stakan un\"}, {\"name\": \"½ stakan bodom uni\"}, {\"name\": \"3 osh qoshiq shakar\"}, {\"name\": \"115 g sovuq saryog'\"}, {\"name\": \"2 tuxum sarig'i. Krem: 2 stakan sut\"}, {\"name\": \"4 tuxum sarig'i\"}, {\"name\": \"⅓ stakan shakar\"}, {\"name\": \"¼ stakan kraxmal\"}, {\"name\": \"vanil va saryog'. Ustiga: 350 g chernika va smorodina.\"}]", "steps": "[{\"text\": \"Korj masalliqlaridan xamir qorib, qolipga yoying va 175°C pechda 35 daqiqa pishirib sovuting.\"}, {\"text\": \"Sut, tuxum sarig'i, shakar va kraxmalni qaynatib quyuq zavarnoy krem pishiring.\"}, {\"text\": \"Kremni korj ustiga surtib, yangi mevalar bilan bezating.\"}]", "is_published": true}, {"title": "Nok va Fundukli Franjipan Tarti (Pear & Hazelnut Tart)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Funduk yong'og'i va saryog'dan pishirilgan franjipan kremi hamda ustiga tizilgan shirin nok parraklari bilan tayyorlanadigan fransuz tarti.", "ingredients": "[{\"name\": \"1 dona tayyor tart korji\"}, {\"name\": \"1 stakan funduk (maydalangan yong'oq)\"}, {\"name\": \"½ stakan shakar\"}, {\"name\": \"90 g saryog'\"}, {\"name\": \"2 dona tuxum\"}, {\"name\": \"vanil va bodom ekstrakti\"}, {\"name\": \"3 dona nok (ingichka parrak kesilgan)\"}, {\"name\": \"Qiyom (o'rik murabbosi suvi).\"}]", "steps": "[{\"text\": \"Funduk, shakar, saryog', tuxum va ekstraktlarni ko'pirtirib franjipan kremi tayyorlang.\"}, {\"text\": \"Kremni korjga yoying va ustidan nok bo'laklarini chiroyli tizib chiqing.\"}, {\"text\": \"175°C pechda 35–40 daqiqa pishiring. Issiq holda ustiga o'rik qiyomini surting.\"}]", "is_published": true}, {"title": "Tuzli Pistali Uvoq, Mevalar va Muzqaymoq (Salted Pistachio Crumbles With Berries and Ice Cream)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Pechda qovurilgan tuzli pista uvoqlari, qaynoq asalli qulupnaylar va muzday muzqaymoq uyg'unligi.", "ingredients": "[{\"name\": \"Pistali uvoq (Krambl) uchun:\\\\n60 g xom pista\\\\n125 g un\\\\n100 g shakar\\\\n40 g makkajo'xori uni (cornmeal)\\\\n1 choy qoshiq yirik tuz\\\\n115 g eritilgan saryog'\\\\nMeva va muzqaymoq uchun:\\\\n700 g yangi qulupnay (bo'laklangan)\\\\n1 osh qoshiq limon sharbati\\\\nYarim choy qoshiq hil (kardamon)\\\\n3 osh qoshiq asal\\\\n1 litr xohlagan turdagi muzqaymoq\"}]", "steps": "[{\"text\": \"Pechni 175°C gacha qizdiring. Pistalarni pishirish varag'iga yoyib, pechda 6–8 daqiqa qovurib oling. Sovigach, oshxona kombaynida kichik bo'lakchalar qoladigan qilib maydalang.\"}, {\"text\": \"Idishda maydalangan pista, un, shakar, makkajo'xori uni va 1 choy qoshiq tuzni aralashtiring. Ustidan eritilgan saryog'ni quyib, barmoqlar bilan uvalab kichik noxotdek uvoqlar hosil qiling.\"}, {\"text\": \"Krambl aralashmasini pergament qog'oz solingan listga yoyib, 175°C pechda tillarang bo'lguncha 20–25 daqiqa pishiring (o'rtasida bir marta aralashtirib qo'ying).\"}, {\"text\": \"Chuqur idishda qulupnay, limon sharbati, hil va bir chimdim tuzni aralashtiring.\"}, {\"text\": \"Kichik tovada asalni qizdiring — 4 daqiqa davomida pufakchalar chiqarib biroz to'qlashguncha qaynating va darhol qulupnaylar ustiga quying. Yaxshilab aralashtirib, 15 daqiqa tindiring.\"}, {\"text\": \"Idishlarga muzqaymoq shariklarini soling, ustidan suvi bilan birga qulupnayli aralashmani quyib, qarsildoq pistali uvoqlardan seping.\"}]", "is_published": true}, {"title": "Yozgi Pomidorli va Rikottali Tart (Summer Tomato and Ricotta Tart With Oat Pastry)", "category": "Pishiriqlar & Tuzli Piroglar", "cook_time_minutes": 50, "difficulty": "o'rtacha", "description": "Sullili korj (xamir), chia urug'lari, ipakdek rikotta pishlog'i va sersuv pomidor bo'laklari bilan pishiriladigan yozgi tart.", "ingredients": "[{\"name\": \"Sullili korj (xamir) uchun:\\\\n90 g suli yormasi (rolled oats)\\\\n50 g chia urug'lari\\\\nYarim choy qoshiq tuz\\\\n140 g bug'doy uni (wholemeal/spelt flour)\\\\n60 g bodom uni\\\\n80 ml zaytun yog'i\\\\n60 ml suv\\\\nIchlik va ustiga:\\\\n240 g rikotta pishlog'i (yoki yumshoq tvorog)\\\\n2 choy qoshiq limon rendasi\\\\n40 g parmezan pishlog'i (qirilgan)\\\\n400 g sersuv pomidor bo'laklari\\\\nYangi rayhon barglari\"}, {\"name\": \"zaytun yog'i\"}, {\"name\": \"tuz va qora murch\"}]", "steps": "[{\"text\": \"Pechni 180°C gacha qizdiring. Kombaynda suli yormasi, chia urug'lari va tuzni mayda uvoq bo'lguncha elang. Bug'doy va bodom unini qo'shib aralashtiring.\"}, {\"text\": \"Zaytun yog'i va suvni birlashtirib, kombayn ishlab turganda unli aralashmaga quyib boring.\"}, {\"text\": \"Xamirni 24 cm diametrli tart qolipiga solib, tubi va chetlariga barmoqlar bilan mahkam presslab yoying. Sanchqi bilan teshikchalar qilib, 180°C pechda 20 daqiqa tillarang bo'lguncha pishiring va to'liq sovuting.\"}, {\"text\": \"Idishda rikotta, limon rendasi, parmezan, tuz va murch bilan yaxshilab ko'pirtiring.\"}, {\"text\": \"Sovigan korj ichiga rikotta kremini tekis yoying. Ustiga pomidor bo'laklari va rayhon barglarini tizib, zaytun yog'i tomizing va murch seping.\"}]", "is_published": true}, {"title": "Mevali Galetta (Fruit Galette)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 45, "difficulty": "oson", "description": "Saryog'li fransuzcha uvalanuvchan xamir ustida shaftoli, o'rik va olxori mevalaridan tayyorlanadigan qarsildoq galetta.", "ingredients": "[{\"name\": \"Xamir uchun:\\\\n200 g un\\\\n100 g sovuq saryog' (kubik kesilgan)\\\\n1 osh qoshiq shakar\\\\n1 chimdim tuz\\\\n4 osh qoshiq muzday suv\\\\nIchlik uchun:\\\\n400 g yangi mevalar (shaftoli\"}, {\"name\": \"o'rik\"}, {\"name\": \"olxori yoki meva aralashmasi)\\\\n3 osh qoshiq shakar\\\\n1 osh qoshiq kraxmal\\\\n1 osh qoshiq mevali djem/murabbo (xohishga ko'ra)\"}]", "steps": "[{\"text\": \"Un, shakar va tuzga sovuq saryog'ni qo'shib, barmoqlar bilan uvalab qarsildoq uvoq holiga keltiring. Muzday suvni quyib tezda xamir to'plang va 30 daqiqa muzlatgichda tindiring.\"}, {\"text\": \"Mevalarni parrak qilib to'g'rang, shakar va kraxmal bilan aralashtiring.\"}, {\"text\": \"Tindirilgan xamirni pergament qog'oz ustida doira shaklida (3-4 mm qalinlikda) yoying.\"}, {\"text\": \"Xamir o'rtasiga djem surting, chetlaridan 4-5 cm joy qoldirib mevalarni tizib chiqing.\"}, {\"text\": \"Xamirning ochiq chetlarini mevalar ustiga bukib taxlang. Buklangan chetlariga shakar seping.\"}, {\"text\": \"190°C pechda 35–40 daqiqa mevalar yumshab, xamiri tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Xitoy Xurmoli (Unab) Pirog (Win Son Bakery's Red Date Cake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 55, "difficulty": "o'rtacha", "description": "Quritilgan qizil xurmo (unab) pyuresi va karamelli qaymoqli glazur bilan pishiriladigan xushbo'y keks.", "ingredients": "[{\"name\": \"Xamir uchun:\\\\n170 g quritilgan qizil xurmo (unab — red dates\"}, {\"name\": \"urug'siz va to'g'ralgan)\\\\nYarim choy qoshiq soda\\\\n155 g un\\\\n2 choy qoshiq qabartma kukun\\\\n1 choy qoshiq tuz\\\\n150 g shakar\\\\n85 g yumshoq saryog'\\\\n2 dona tuxum\\\\nYarim choy qoshiq vanil ekstrakti\\\\nGlazur uchun:\\\\n4 dona qizil xurmo (tasmalarga bo'lingan)\\\\n60 ml qaymoq\\\\n60 g saryog'\\\\n50 g jigarrang shakar\\\\nYarim choy qoshiq tuz\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Qolipni saryog'lang. Idishda 170 g xurmo, soda va 180 ml suvni qaynatib, past olovda 3 daqiqa dimlang. Suvi tortilgach sovuting.\"}, {\"text\": \"Un, qabartma kukun va tuzni elang. Alohida idishda saryog', shakar va vanilni mikserda 3 daqiqa ko'pirtiring. Tuxumlarni bittalab qo'shing.\"}, {\"text\": \"Quruq masalliqlarning yarmini, so'ng sovigan xurmo pyuresini, keyin qolgan unni qo'shib past tezlikda aralashtiring. Qolipga quyib, 175°C pechda 25–30 daqiqa pishiring.\"}, {\"text\": \"Glazur: Idishda qaymoq, saryog', jigarrang shakar va tuzni eritib, 5 daqiqa quyulguncha qaynating. Sovigan xurmo tasmalari bilan pirog ustini bezang va iliq glazurni ustidan quyib chiqing.\"}]", "is_published": true}, {"title": "Koreyscha Shiringina Qora Lobiya (Kong Jaban / Korean Sweet Black Beans)", "category": "Koreys & Dunyo Oshxonasi", "cook_time_minutes": 75, "difficulty": "oson", "description": "Soya sousi, shakar va kunchut yog'ida uzoq dimlab pishiriladigan Koreyscha mashhur shirin-tuzli qora lobiya garniri.", "ingredients": "[{\"name\": \"250 g quritilgan qora lobiya (loviya)\\\\n2 litr dashi bulyoni yoki suv\\\\n240 ml soya sousi\\\\n150 g shakar\\\\n2 osh qoshiq qovurilgan kunchut yog'i\\\\n1 osh qoshiq qovurilgan kunchut urug'lari\"}]", "steps": "[{\"text\": \"Lobiyani sovuq suvda kamida 8–12 soat ivitib oling va suvsizlantiring.\"}, {\"text\": \"Qozonga lobiyani solib, dashi bulyoni (yoki suv) va soya sousini quying. O'rta-yuqori olovda qaynatib oling, so'ng past olovda 1 soat davomida sekin dimlang.\"}, {\"text\": \"Lobiya yumshab, suyuqligi kamaygach, shakar, kunchut yog'i va kunchut urug'larini qo'shib yaxshilab aralashtiring. (Shakarni boshida solmang, aks holda lobiya qattiq bo'lib qoladi).\"}, {\"text\": \"Suyuqligi quyuq va yaltiroq holatga kelguncha yana 5-10 daqiqa pishiring. Sovutib, muzlatgichga qo'ying va garnir sifatida torting.\"}]", "is_published": true}, {"title": "Lavlagi va Mevali Salqin Ichimlik (Lágrimas de la Virgen / Beet Cooler With Fruits)", "category": "Ichimliklar & Kokteyllar", "cook_time_minutes": 20, "difficulty": "oson", "description": "Qizil lavlagi toza sharbati, olma, banan, apelsin va limon sharbati solingan vitaminlarga boy tetiklashtiruvchi salqin drink.", "ingredients": "[{\"name\": \"4 dona qizil lavlagi\\\\n2 litr suv\\\\n200 g shakar\\\\n1 dona kichik olma (kubik to'g'ralgan)\\\\n1 dona banan (kubik to'g'ralgan)\\\\n1 dona apelsin (tozalangan\"}, {\"name\": \"to'g'ralgan)\\\\n4 yaproq romen salat bargi (ingichka tasmasimon to'g'ralgan)\\\\n1 dona limon sharbati\"}]", "steps": "[{\"text\": \"Lavlagini tozalab, sharbat chiqargich orqali toza sharbatini chiqarib oling.\"}, {\"text\": \"Katta ko'zachada suv va shakarni shakar to'liq eriguncha aralashtiring. Ustidan lavlagi sharbatini quying.\"}, {\"text\": \"Ko'zachani muzlatgichda to'liq sovuting.\"}, {\"text\": \"Dasturxonga tortish oldidan to'g'ralgan olma, banan, apelsin, salat barglari hamda limon sharbatini qo'shib aralashtiring (limon mevalar qarayib ketishining oldini oladi). Muz kubiklari bilan uzating.\"}]", "is_published": true}, {"title": "Gvayava, Greypfrut va Rozmarinli Agua Freska (Guava, Grapefruit, and Rosemary Agua Fresca)", "category": "Ichimliklar & Kokteyllar", "cook_time_minutes": 15, "difficulty": "oson", "description": "Yangi greypfrut sharbati, gvayava pyuresi va rozmarin barglari bilan tayyorlanadigan tropik agua freska.", "ingredients": "[{\"name\": \"700 ml suv\\\\n3 dona greypfrut sharbati (yangi siqilgan)\\\\n430 g gvayava pyuresi (guava puree)\\\\n1 shoxcha yangi rozmarin barglari\\\\n100 g shakar (ta'bga ko'ra)\\\\nMuz kubiklari\"}]", "steps": "[{\"text\": \"Blender idishida suv, greypfrut sharbati, gvayava pyuresi va rozmarin barglarini solib to'liq silliq bo'lguncha ko'pirtiring.\"}, {\"text\": \"Hosil bo'lgan aralashmani mayda elakdan ko'zachaga o'tkazib elang.\"}, {\"text\": \"Shakarni ta'bga ko'ra qo'shib, eriguncha aralashtiring.\"}, {\"text\": \"Stakanlarga muz to'ldirib, ustidan ichimlikni quying va rozmarin shoxchasi bilan bezating.\"}]", "is_published": true}, {"title": "Meksikancha Mevali Salqin Ichimlik (Aguas Frescas / Mexican Fruit Coolers)", "category": "Ichimliklar & Kokteyllar", "cook_time_minutes": 15, "difficulty": "oson", "description": "Tarvuz, ananas, qovun, papaya, qulupnay yoki mango mevalari mag'zidan pishiriladigan meksikancha tetiklantiruvchi ichimlik.", "ingredients": "[{\"name\": \"600 g to'g'ralgan mevalar (tarvuz\"}, {\"name\": \"qovun\"}, {\"name\": \"ananas\"}, {\"name\": \"papaya\"}, {\"name\": \"qulupnay yoki mango)\\\\n1 litr suv\\\\n100 g shakar\\\\nMuz kubiklari\\\\nLimon bo'laklari\"}]", "steps": "[{\"text\": \"Katta ko'zachada shakar va suvni aralashtirib shakarni eriting. Ushbu aralashmadan 240 ml ajratib oling.\"}, {\"text\": \"Blenderga to'g'ralgan mevalar va ajratib olingan shakarli suvni solib silliq pyure bo'lguncha ko'pirtiring.\"}, {\"text\": \"Mevali pyureni ko'zachadagi shakarli suvga elak orqali o'tkazing, yog'och qoshiq bilan meva mag'zini ezib suvini ajrating.\"}, {\"text\": \"Yaxshilab aralashtirib, muz va limon bo'laklari bilan sovuq holda torting.\"}]", "is_published": true}, {"title": "Yashil Piyozli Qarsildoq Pirojkalar va Chili-Zanjabilli Sous (Scallion Pancakes With Chili-Ginger Dipping Sauce)", "category": "Salatlar & Gazaklar", "cook_time_minutes": 30, "difficulty": "o'rtacha", "description": "Muzday gazlangan suvda tayyorlangan xamir va yashil piyozli qarsildoq mini-pirojkalar hamda chili-zanjabilli sous.", "ingredients": "[{\"name\": \"Sous uchun:\\\\n1 bo'lak zanjabil (ingichka to'g'ralgan)\\\\n2 osh qoshiq soya sousi\"}, {\"name\": \"2 osh qoshiq guruch sirkasi\"}, {\"name\": \"1 choy qoshiq chili yog'i\"}, {\"name\": \"1 choy qoshiq shakar\\\\nXamir va ichlik uchun:\\\\n125 g un\"}, {\"name\": \"30 g kraxmal\"}, {\"name\": \"1 choy qoshiq tuz\"}, {\"name\": \"1 choy qoshiq shakar\\\\n240 ml muzday gazlangan suv (club soda)\"}, {\"name\": \"2 choy qoshiq soya sousi\"}, {\"name\": \"1 choy qoshiq kunchut yog'i\\\\n150 g ingichka to'g'ralgan yashil piyoz\"}, {\"name\": \"4 osh qoshiq o'simlik yog'i\"}]", "steps": "[{\"text\": \"Sous: Idishda zanjabil, soya sousi, sirka, chili yog'i va shakarni shakar eriguncha ko'pirtiring va chetga suring.\"}, {\"text\": \"Xamir: Katta idishda un, kraxmal, tuz va shakarni aralashtiring. Alohida idishda gazlangan suv, soya sousi va kunchut yog'ini birlashtiring. Quyib, silliq bo'lguncha aralashtiring (ko'p aralashtirmang). Yashil piyozni xamirga qo'shib aralashtiring.\"}, {\"text\": \"Qovurish: Tovada 1 osh qoshiq o'simlik yog'ini qizdiring. Xamirning to'rtdan bir qismini quyib, past-o'rta olovda 2 daqiqa tillarang bo'lguncha pishiring. Agdarib, yassilab presslang va yana 1-2 daqiqa qarsildoq bo'lguncha pishiring.\"}, {\"text\": \"Qolgan xamir va yog' bilan yana 3 dona quymoq pishiring. Bo'laklarga bo'lib, zanjabilli sous bilan uzating.\"}]", "is_published": true}, {"title": "\"Kamuflyaj\" Shokoladli va Chizkeykli Brauni (Camouflage Chocolate Fudge Brownies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 50, "difficulty": "o'rtacha", "description": "To'q shokoladli quyuq brauni va oq hamda kakao-pishloqli cream cheese qatlamlarining kamuflyaj naqshli pirogi.", "ingredients": "[{\"name\": \"Tvorogli (Cream Cheese) qatlam:\\\\n225 g cream cheese\"}, {\"name\": \"1 dona tuxum\"}, {\"name\": \"65 g shakar\"}, {\"name\": \"yarim choy qoshiq vanil\"}, {\"name\": \"yarim choy qoshiq tuz\"}, {\"name\": \"1.5 choy qoshiq kakao kukuni\\\\nShokoladli Brauni qatlam:\\\\n150 g saryog'\"}, {\"name\": \"200 g shakar\"}, {\"name\": \"80 g kakao kukuni\"}, {\"name\": \"yarim choy qoshiq tuz\"}, {\"name\": \"1 choy qoshiq espresso kukuni\\\\n2 dona tuxum\"}, {\"name\": \"yarim choy qoshiq vanil\"}, {\"name\": \"65 g un\"}]", "steps": "[{\"text\": \"Pechni 165°C ga qizdiring. 20x20 cm qolipga pergament qog'oz soling.\"}, {\"text\": \"Cream cheese-ni issiqlikka chidamli idishda bug' hammomida 5 daqiqa yumshating. Olovdan olib silliq bo'lguncha ezib, 1 dona tuxum, 65 g shakar, yarim choy qoshiq vanil va yarim choy qoshiq tuzni ko'pirtiring. Yarmini ajratib, 1.5 choy qoshiq kakao qo'shing.\"}, {\"text\": \"Idishda saryog', espresso kukuni, 200 g shakar, 80 g kakao va yarim choy qoshiq tuzni bug' hammomida saryog' eriguncha eritib, 5 daqiqa sovuting. 2 dona tuxum va vanilni qo'shib ko'pirtiring. Unni solib yaxshilab aralashtiring.\"}, {\"text\": \"Brauni xamirining ko'p qismini qolipga tekis yoying. Ustiga oq va shokoladli tvorog massasini va qolgan brauni xamirini navbatma-navbat dog' sifat (\\\"kamuflyaj\\\") qilib tomizing.\"}, {\"text\": \"165°C pechda 22–25 daqiqa pishiring. Sovugach bo'laklarga bo'ling.\"}]", "is_published": true}, {"title": "Smetana va Piyozli Yumshoq Biskvitlar (Sour Cream and Onion Biscuits)", "category": "Pishiriqlar & Xamirlar", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Kat-kat saryog'li xamir, smetana va yashil piyoz aromati bilan pechda tillarang pishiriladigan biskvit-bulochkalar.", "ingredients": "[{\"name\": \"310 g un\\\\n2 choy qoshiq qabartma kukun (baking powder)\\\\nYarim choy qoshiq soda\\\\n1.5 choy qoshiq tuz\"}, {\"name\": \"1 choy qoshiq qora murch\\\\n1 choy qoshiq shakar\\\\n150 g sovuq saryog' (kubik bo'lingan) + 30 g eritilgan saryog'\\\\n80 g ingichka to'g'ralgan yashil piyoz\\\\n300 g smetana\\\\nYirik dengiz tuzi (flaky sea salt)\"}]", "steps": "[{\"text\": \"Pechni 215°C gacha qizdiring. Idishda un, qabartma kukun, soda, tuz, murch va shakarni elang. Sovuq saryog'ni qo'shib, barmoqlar bilan uvalab noxotdek uvoqlar hosil qiling. Yashil piyozni qo'shing.\"}, {\"text\": \"O'rtasini ochib smetanani quying, sanchqi bilan xamir holiga keltiring. Stolda xamirni 20x10 cm to'rtburchak qilib yoying.\"}, {\"text\": \"Xamirni konvertga o'xshab uchga taxlang. Yana yoyib, yana uchga taxlang (bu kat-kat bo'lishini ta'minlaydi). 8 ta kvadrat bo'lakka bo'ling.\"}, {\"text\": \"Listga tizib, ustiga eritilgan saryog' surting va yirik tuz seping. 215°C pechda 18–22 daqiqa tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Grechka Unli va Shokoladli Tuzli Pechenye (Salty Buckwheat Chocolate Chunk Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 35, "difficulty": "o'rtacha", "description": "Grechka uni, jigarrang shakar va yirik shokolad bo'laklari solinib pishiriladigan og'izda eriydigan tuzli pechenye.", "ingredients": "[{\"name\": \"125 g un\\\\n65 g grechka uni (buckwheat flour)\\\\nYarim choy qoshiq qabartma kukun\"}, {\"name\": \"yarim choy qoshiq soda\\\\n1 choy qoshiq tuz\\\\n115 g saryog'\\\\n130 g jigarrang shakar\"}, {\"name\": \"100 g shakar\\\\n1 dona tuxum + 2 dona tuxum sarig'i\"}, {\"name\": \"1 choy qoshiq vanil\\\\n170 g achchiq shokolad bo'laklari (chopped chocolate)\"}]", "steps": "[{\"text\": \"Saryog'ni past olovda eritib oling. Ikki xil un, qabartma kukun, soda va tuzni elang.\"}, {\"text\": \"Eritilgan saryog' va ikkala shakarni mikserda 30 soniya ko'pirtiring. Tuxum va tuxum sariqlarini bittalab qo'shing, vanilni solib krem holatiga keltiring.\"}, {\"text\": \"Quruq masalliqlarni va shokolad bo'laklarini qo'shib yumshoq xamir qoring. Idishni yopib, 2 soat muzlatgichda sovuting.\"}, {\"text\": \"Pechni 190°C ga qizdiring. Xamirdan 2 osh qoshiqlik shariklar yasab, listga 5 cm masofada tizib chiqing.\"}, {\"text\": \"190°C pechda 8–10 daqiqa chetlari tillarang bo'lguncha pishiring. Pechdan olgach, listni stolga sekin urib yassilang va ustiga yirik tuz seping.\"}]", "is_published": true}, {"title": "Kokosli va Guruch Unli Mochi Pirogi (Mochi Cake, Any Way You Want It)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 70, "difficulty": "oson", "description": "Yapishqoq guruch uni (mochiko), kokos suti va saryog'dan pishiriladigan qarsildoq ustli va elastik ichli Osiyo pirogi.", "ingredients": "[{\"name\": \"250 g yapishqoq guruch uni (glutinous sweet rice flour / mochiko)\\\\n300 g shakar\\\\n400 ml kokos suti (yoki qaymoq)\\\\n90 g eritilgan saryog' (yoki kokos yog'i)\\\\n2 dona tuxum\\\\n2 choy qoshiq vanil\\\\n1 choy qoshiq tuz\"}, {\"name\": \"1 choy qoshiq qabartma kukun\\\\n30 g kokos qiyg'ichi yoki kunchut (ustiga)\"}]", "steps": "[{\"text\": \"Pechni 175°C gacha qizdiring. Qolipni saryog'lab, shakar sepib tayyorlang.\"}, {\"text\": \"Idishda shakar, eritilgan saryog' va kokos sutini mikserda aralashtiring. Tuxum, vanil va tuzni qo'shing.\"}, {\"text\": \"Guruch uni va qabartma kukunni qo'shib silliq xamir bo'lguncha ko'pirtiring.\"}, {\"text\": \"Xamirni qolipga quyib, ustiga kokos qiyg'ichi yoki kunchut seping.\"}, {\"text\": \"175°C pechda 55–65 daqiqa usti qarsildoq va tillarang bo'lguncha pishiring. To'liq sovutib kosing.\"}]", "is_published": true}, {"title": "Apelsinli va Shokoladli Keks (Orange Chocolate Loaf Cake From Florida)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 75, "difficulty": "o'rtacha", "description": "Kakao, qaymoq va apelsin rendasi xamiri hamda pishgach surtiladigan xushbo'y apelsinli shirin qiyom biskviti.", "ingredients": "[{\"name\": \"Xamir uchun:\\\\n150 g un\"}, {\"name\": \"50 g kakao kukuni\"}, {\"name\": \"2 choy qoshiq qabartma kukun\"}, {\"name\": \"yarim choy qoshiq tuz\\\\n200 g shakar\"}, {\"name\": \"240 ml suyuq qaymoq (heavy cream)\"}, {\"name\": \"2 dona tuxum\"}, {\"name\": \"1 choy qoshiq vanil\\\\n1 dona apelsin po'stining qirilgan rendasi\\\\nApelsin qiyomi uchun:\\\\n80 ml apelsin sharbati\"}, {\"name\": \"3 osh qoshiq shakar\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Loaf (keks) qolipini yog'lab, non uvoqlari seping. Un, kakao, qabartma kukun, tuz va shakarni birga elang.\"}, {\"text\": \"Qaymoq va vanilni mikserda biroz ko'pirtiring. Tuxumlarni bittalab qo'shib ko'pirtirishda davom eting.\"}, {\"text\": \"Elangan quruq masalliqlarni past tezlikda qo'shing va apelsin rendasini solib aralashtiring.\"}, {\"text\": \"Xamirni qolipga quyib, 175°C pechda 1 soat 5 daqiqa pishiring.\"}, {\"text\": \"Qiyom: Apelsin sharbati va shakarni aralashtirib qo'ying. Keks pishgach, issiq holda ustiga va yon atroflariga apelsinli qiyomni cho'tka bilan surtib chiqib sovuting.\"}]", "is_published": true}, {"title": "Qaymoqli Mayin Keks (Whipped Cream Cake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 45, "difficulty": "oson", "description": "Ko'pirtirilgan sovuq qaymoq, tuxum va elangan un aralashmasidan tayyorlanadigan g'ovakli va momiq keks.", "ingredients": "[{\"name\": \"280 g maxsus tort uni (cake flour) yoki elangan oddiy un\\\\n2 choy qoshiq qabartma kukun (baking powder)\\\\nYarim choy qoshiq tuz\\\\n360 ml sovuq suyuq qaymoq (heavy cream)\\\\n3 dona tuxum (xonaki haroratda)\\\\n225 g shakar\\\\n1 choy qoshiq vanil ekstrakti\"}]", "steps": "[{\"text\": \"Pechni 175°C gacha qizdiring. Teshikli keks qolipini (tube pan) yog'lang va un sepib tayyorlang.\"}, {\"text\": \"Idishda un, qabartma kukun va tuzni elab aralashtiring.\"}, {\"text\": \"Suyuq qaymoqni mikserda quyuq va qattiq piklar hosil bo'lguncha yaxshilab ko'pirtiring.\"}, {\"text\": \"Alohida idishda tuxum va vanilni sanchqi bilan ko'pirtirib, ko'pirtirilgan qaymoqqa oz-ozdan qo'shing. Shakarni sekin-asta solib 30 soniya ko'pirtiring.\"}, {\"text\": \"Elangan unli aralashmani ikki bo'lakka bo'lib solib, lapatka bilan pastdan yuqoriga ehtiyotkorlik bilan buklab aralashtiring (qaymoq cho'kib qolmasin).\"}, {\"text\": \"Qolipga quyib, 175°C pechda 25–35 daqiqa pishiring. 10 daqiqa sovutib, agdarib oling va shakar kukuni bilan bezating.\"}]", "is_published": true}, {"title": "Hamirturushli Laymli va Rikottali Pechenye (Sourdough Key Lime Ricotta Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "O'ziga xos nordon-shirin laym va rikotta pishlog'i hamda achigan hamirturushli og'izda eriydigan pechenye.", "ingredients": "[{\"name\": \"113 g saryog' (yumshatilgan)\\\\n200 g shakar\\\\n1 dona tuxum\\\\n120 g achigan hamirturush (sourdough starter)\\\\n125 g rikotta pishlog'i\\\\n1 dona laym po'stining qirilgan rendasi\\\\n1 choy qoshiq vanil ekstrakti\\\\n360 g un\\\\n15 g (1 osh qoshiq) qabartma kukun (Razrixlitel)\\\\nYarim choy qoshiq dengiz tuzi\\\\nGlazur va bezak uchun:\\\\n90 g shakar kukuni (elangan)\\\\n1-2 dona laym sharbati va rendasi\"}]", "steps": "[{\"text\": \"Pechni 180°C gacha qizdiring. Ikki dona pishirish varag'iga pergament qog'oz solib tayyorlang.\"}, {\"text\": \"Idishda yumshoq saryog' va shakarni mikserda 3–4 daqiqa davomida mayin bo'lguncha ko'pirtiring. Tuxumni solib aralashtiring.\"}, {\"text\": \"Hamirturush, rikotta pishlog'i, laym rendasi va vanilni qo'shib mikserda aralashtiring (aralashma biroz donador bo'lishi normal holat).\"}, {\"text\": \"Alohida idishda un, qabartma kukun (Razrixlitel) va tuzni elang. Quruq masalliqlarni past tezlikda asta-sekin qo'shib xamir qoring. Idishni plyonka bilan yopib, 30 daqiqa muzlatgichda tindiring.\"}, {\"text\": \"Xamirdan osh qoshiq yordamida bo me'yorda sharikchalar ajratib listga tizib chiqing.\"}, {\"text\": \"180°C pechda 15–17 daqiqa pishiring. Pishgach sim panjarada to'liq sovuting.\"}, {\"text\": \"Glazur: Shakar kukuniga laym sharbatini oz-ozdan quyib, silliq va oquvchan massa bo'lguncha ko'pirtiring.\"}, {\"text\": \"Sovigan pechenyelar ustiga glazur quyib, qirilgan laym rendasi bilan bezating.\"}]", "is_published": true}, {"title": "Dolchin va Shakarli Hamirturushli Vafli (Cinnamon Sugar Sourdough Waffles)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 30, "difficulty": "oson", "description": "Qarsildoq vaflilar, dolchinli shakar va yangi mevalar va klyon siropi bilan uzatiladigan noshtabop shirinlik.", "ingredients": "[{\"name\": \"Dolchinli shakar uchun:\\\\n50 g shakar\\\\n1 choy qoshiq dolchin kukuni\\\\nXamir uchun:\\\\n120 g achigan hamirturush (sourdough starter)\\\\n240 ml sut\\\\n42 g eritilgan saryog' (bo'lingan)\\\\n1 dona tuxum\\\\n120 g un\\\\n12 g shakar\\\\n10 g (2 choy qoshiq) qabartma kukun (Razrixlitel)\\\\nYarim choy qoshiq dengiz tuzi\\\\nTortish uchun:\\\\n165 g kubik to'g'ralgan ananas\\\\nBir siqim yangi mevalar (qulupnay\"}, {\"name\": \"chernika)\\\\n30 g kokos qiyg'ichi\\\\nKlyon siropi (yoki asal)\"}]", "steps": "[{\"text\": \"Chuqur idishda 50 g shakar va dolchinni aralashtirib qo'ying.\"}, {\"text\": \"Vafli pishirgichni yoqib qizdiring. Katta idishda achigan hamirturush, sut, 28 g eritilgan saryog' va tuxumni yaxshilab ko'pirtiring. Un, 12 g shakar, qabartma kukun (Razrixlitel) va tuzni qo'shib silliq bo'lguncha aralashtiring.\"}, {\"text\": \"Vafli qolipini yog'lang. Xamirdan quyib, tillarang va qarsildoq bo'lguncha 3–5 daqiqa pishiring.\"}, {\"text\": \"Pishgan vaflilarga qolgan eritilgan saryog'dan surting va dolchinli shakar aralashmasiga ikkala tarafini botirib oling.\"}, {\"text\": \"Tayyor vaflilarni ananas, mevalar hamda kokos qiyg'ichi bilan bezatib, klyon siropi bilan dasturxonga torting.\"}]", "is_published": true}, {"title": "Chernikali va Limonli Makkajo'xori Mafinlari (Blueberry Lemon Corn Muffins)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Makkajo'xori uni, chernika rezavorlari va limon aromati bilan tayyorlanadigan mitti va yumshoq mafinlar.", "ingredients": "[{\"name\": \"60 g saryog' (eritilgan va sovutilgan)\\\\n95 g un\\\\n1.5 choy qoshiq qabartma kukun (Razrixlitel)\\\\n80 g makkajo'xori uni (cornmeal)\\\\n110 g shakar\\\\n1 osh qoshiq limon rendasi\\\\n120 ml sut\\\\n2 dona tuxum sarig'i\\\\n75 g chernika (teng ikkiga bo'lingan)\"}]", "steps": "[{\"text\": \"Pechni 190°C gacha qizdiring. 6 dona mafin qolipiga qog'oz korzinkachalar joylashtiring.\"}, {\"text\": \"Idishda un va qabartma kukun (Razrixlitel)ni elang. Makkajo'xori uni, 100 g shakar, limon rendasi va bir chimdim tuzni solib aralashtiring.\"}, {\"text\": \"Alohida idishda eritilgan saryog', sut va tuxum sariqlarini ko'pirtiring. Quruq masalliqlar va chernikaning yarmi bilan birga ohista aralashtiring.\"}, {\"text\": \"Xamirni qoliplarga teng bo'lib quying. Qolgan chernikalarni mafinlar ustiga botirib tizib chiqing va 10 g shakar seping.\"}, {\"text\": \"190°C pechda 15 daqiqa tillarang bo'lguncha pishiring. Sim panjarada sovutib uzating.\"}]", "is_published": true}, {"title": "Ziravorli Mermer Keks (Swirl Spice Cake)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 90, "difficulty": "o'rtacha", "description": "Pekan yong'og'i shtreyzeli, smetana xamiri hamda apelsinli shirin glazur bilan pishiriladigan mermer keks.", "ingredients": "[{\"name\": \"Shtreyzel (uvoq) uchun:\\\\n100 g maydalangan pekan yong'og'i\\\\n45 g qahva va ziravorlar aralashmasi (Spice Mix)\\\\n75 g jigarrang shakar\\\\n24 g un\\\\n1 choy qoshiq tuz\\\\n60 g eritilgan saryog'\\\\nXamir va glazur uchun:\\\\n250 g un\\\\nYarim choy qoshiq qabartma kukun (Razrixlitel)\\\\nChorak choy qoshiq soda\\\\nYarim choy qoshiq tuz\\\\n250 g shakar\\\\n170 g saryog' (xonaki haroratda)\\\\n3 dona tuxum\\\\n120 g smetana\\\\n2 choy qoshiq vanil ekstrakti\\\\n28 g shakar kukuni + 1 choy qoshiq apelsin sharbati\"}]", "steps": "[{\"text\": \"Pechni 165°C gacha qizdiring. Keks qolipini yog'lab, pergament soling.\"}, {\"text\": \"Uvoq: Yong'oq, ziravorlar aralashmasi, jigarrang shakar, un va tuzni aralashtirib, saryog' quyib uvoq holiga keltiring.\"}, {\"text\": \"Idishda un, qabartma kukun (Razrixlitel), soda va tuzni elang. Mikserda saryog' va shakarni 6–8 daqiqa mayin ko'pirtiring. Tuxumlarni bittalab qo'shing. Unli aralashmaning yarmini, so'ng smetana va vanilni, keyin qolgan unni solib aralashtiring.\"}, {\"text\": \"Xamirning yarmini qolipga quyib, ustiga uvoq aralashmasini yoying. Qolgan xamirni quyib, pichoq bilan mermer naqsh hosil qilib aralashtiring.\"}, {\"text\": \"165°C pechda 80–90 daqiqa pishiring. Sovugach qolipdan oling.\"}, {\"text\": \"Shakar kukuni va apelsin sharbatini ko'pirtirib glazur tayyorlang va keks ustidan quying.\"}]", "is_published": true}, {"title": "Qahvali va Ziravorli Aralashma (Savory-to-Sweet Coffee Spice Mix)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 5, "difficulty": "oson", "description": "Qahva, apelsin rendasi, dolchin va hil urug'laridan tayyorlanadigan shirinliklar uchun xushbo'y ziravor.", "ingredients": "[{\"name\": \"3 osh qoshiq asalari gulchangi kukuni (bee pollen)\\\\n3 osh qoshiq mayda tortilgan qahva (instant emas)\\\\n2 osh qoshiq quritilgan apelsin po'stlog'i rendasi\\\\n2 osh qoshiq dolchin kukuni\\\\n2 choy qoshiq kardamon (hil) kukuni\\\\n2 choy qoshiq maydalangan fenxel urug'lari\"}]", "steps": "[{\"text\": \"Barcha ziravor masalliqlarini toza va quruq shisha bankaga soling.\"}, {\"text\": \"Qopqog'ini mahkam yopib, bir xil massa bo'lguncha yaxshilab silkiting.\"}, {\"text\": \"Pishiriqlar, kekslar va shirinliklarga xushbo'y ta'm berish uchun foydalaning. (Xona haroratida 1 oy saqlash mumkin).\"}]", "is_published": true}, {"title": "Karam va Kartoshkali Pirog (Cabbage Potato Pie)", "category": "Pishiriqlar & Tuzli Piroglar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Kartoshka pyuresi, qovurilgan karam, dudlangan bekon va cheddar pishlog'i solib pechda pishiriladigan tuzli pirog.", "ingredients": "[{\"name\": \"900 g kartoshka (tozalanib\"}, {\"name\": \"bo'lingan)\\\\n1 choy qoshiq tuz\\\\n60 g saryog' (bo'lingan)\\\\n1 dona savoy karami (Savoy cabbage)\\\\n85 g dudlangan bekon bo'laklari (mayda to'g'ralgan)\\\\nYarim dona qizil piyoz (ingichka to'g'ralgan)\\\\n2 osh qoshiq olma sirkasi\\\\n1 choy qoshiq timyan barglari\"}, {\"name\": \"1 choy qoshiq qora murch\\\\n2 dona tuxum\\\\n180 ml qaymoq (heavy cream)\\\\n140 g qirilgan cheddar pishlog'i\"}]", "steps": "[{\"text\": \"Pechni 200°C ga qizdiring. Kartoshkani tuzli suvda 20 daqiqa qaynatib oling va suvidan ajratib 30 g saryog' bilan ezib pyure qiling.\"}, {\"text\": \"Karamning 10 dona butun bargini ajratib, tuzli suvda 8 daqiqa qaynatib oling va sovuq suvda sovutib qurutib oling. Qolgan karamni ingichka to'g'rang.\"}, {\"text\": \"Tovada bekon, to'g'ralgan karam va piyozni 20 daqiqa qizartirib qovuring. Sirka, timyan, murch va tuz qo'shing.\"}, {\"text\": \"Kartoshka pyuresiga tuxum, qaymoq, qovurilgan karamli aralashma va pishloqni qo'shib yaxshilab aralashtiring.\"}, {\"text\": \"Qolip tubi va yonlariga qaynagan karam barglarini yoying. Kartoshkali massani solib tekislang va barglarning chetini ustiga yoping. Ustiga qolgan saryog'ni bo'lib soling.\"}, {\"text\": \"200°C pechda 30–35 daqiqa tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Xurmoli Achchiq-Shirin Somon Baliq (Spicy Sweet-and-Sour Salmon With Dates / Qaliyeh-e Khorma)", "category": "Quyuq Taomlar", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Qizil somon balig'i filetosi, xurmo qiyomi va achchiq sous hamda bodringli yangi salat aralashmasi.", "ingredients": "[{\"name\": \"Bodring va piyozli salat uchun:\\\\n4 osh qoshiq kashnich urug'lari (qovurilgan)\\\\n1 dona qizil piyoz\"}, {\"name\": \"12 dona kichik bodring (kubik to'g'ralgan)\\\\n4 osh qoshiq olma sirkasi\"}, {\"name\": \"1.5 choy qoshiq tuz\\\\nBaliq va sous uchun:\\\\n4–6 bo'lak somon balig'i (losos) filetosi\\\\n1 osh qoshiq un\"}, {\"name\": \"1 choy qoshiq kurkuma\"}, {\"name\": \"yarim choy qoshiq murch\"}, {\"name\": \"tuz\\\\n60 ml zaytun yog'i\\\\n5 tish sarimsoq (qirilgan)\\\\n240 ml olma sirkasi\"}, {\"name\": \"2 osh qoshiq xurmo qiyomi (date molasses)\\\\n1 choy qoshiq achchiq qizil murch\"}, {\"name\": \"1 osh qoshiq quritilgan shambalila (fenugreek) barglari\\\\n5 dona medjool xurmosi (urug'siz\"}, {\"name\": \"ikkiga bo'lingan)\\\\nYangi ko'katlar (kashnich\"}, {\"name\": \"rayhon\"}, {\"name\": \"yashil piyoz)\"}]", "steps": "[{\"text\": \"Salat: Idishda piyoz, bodring, kashnich urug'lari, tuz va sirkani aralashtirib chetga suring.\"}, {\"text\": \"Un, kurkuma, murch va tuzni aralashtirib, baliq filetosining ikkala tomoniga surting.\"}, {\"text\": \"Tovada 2 osh qoshiq zaytun yog'ida baliqlarni har bir tomonini 1 daqiqadan qizartirib oling va idishga chiqaring.\"}, {\"text\": \"Shu tovaga qolgan yog' va sarimsoqni solib 1-2 daqiqa qovuring. Sirka, xurmo qiyomi, achchiq murch va shambalilani solib aralashtiring.\"}, {\"text\": \"Baliqlarni tovaga qaytarib, past olovda 10–15 daqiqa sous quyulguncha dimlang. Oxirida xurmo bo'laklarini qo'shing.\"}, {\"text\": \"Dasturxonga yangi ko'katlar va bodringli salat bilan birga torting.\"}]", "is_published": true}, {"title": "Shokolad va Bodomli Fadj (Chocolate-Almond Fridge Fudge)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 15, "difficulty": "oson", "description": "Achchiq shokolad, avokado va bodom pastasi bilan muzlatgichda tayyorlanadigan tetik va shirin fadj deseri.", "ingredients": "[{\"name\": \"30 g bodom parraklari (tostlangan)\\\\n115 g achchiq shokolad (kamida 60% kakao)\\\\nYarim dona pishgan avokado\\\\n80 ml klyon siropi (yoki asal)\\\\n80 g bodom pastasi (almond butter)\\\\n1 osh qoshiq kakao kukuni\\\\nYarim choy qoshiq tuz va yirik dengiz tuzi\"}]", "steps": "[{\"text\": \"Qolipga pergament qog'oz soling. Bodom parraklarini tovada qovurib maydalang.\"}, {\"text\": \"Achchiq shokoladni mikrotulqinli pechda yoki bug' hammomida eritib sovuting.\"}, {\"text\": \"Blenderda avokado, klyon siropi va bodom patasini silliq bo'lguncha ko'pirtiring. Kakao kukuni, tuz va 2 osh qoshiq sovuq suv qo'shib aralashtiring.\"}, {\"text\": \"Eritilgan shokoladni qo'shib, bir xil konsistensiyaga kelguncha urib oling.\"}, {\"text\": \"Massani qolipga tekis yoyib, ustiga bodom parraklari va yirik dengiz tuzi seping.\"}, {\"text\": \"Muzlatgichda kamida 1 soat qotirib, so'ng bo'laklarga bo'ling.\"}]", "is_published": true}, {"title": "Inglizcha Mafinda Noshtabop Sendvich (Breakfast Sandwich on an English Muffin)", "category": "Salatlar & Gazaklar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Qizartirib qovurilgan piyoz, cheddar pishlog'i va tuxum bilan inglizcha muffinda pishiriladigan mazali sendvich.", "ingredients": "[{\"name\": \"1 dona qizil piyoz (halqa qilib to'g'ralgan)\\\\n1 choy qoshiq soya sousi\"}, {\"name\": \"yarim choy qoshiq sarimsoq kukuni\\\\n30 ml zaytun yog'i\\\\n30 g to'g'ralgan ko'katlar (rayhon\"}, {\"name\": \"kashnich\"}, {\"name\": \"ukrop)\\\\n2 osh qoshiq achchiq sous (hot sauce)\\\\n15 g saryog'\\\\n4 dona tuxum\\\\n2 dona inglizcha muffin (non)\\\\n60 g cheddar pishlog'i (bo'laklangan)\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Piyoz, soya sousi, sarimsoq kukuni va 1 osh qoshiq yog'ni aralashtirib listda 25–35 daqiqa qizartirib pishiring.\"}, {\"text\": \"Idishda ko'katlar, achchiq sous va 1 osh qoshiq zaytun yog'ini aralashtiring.\"}, {\"text\": \"Tovada saryog'ni eritib, ko'pirtirilgan tuxumlarni 1-2 daqiqa yumshoq qilib pishirib oling.\"}, {\"text\": \"Muffin nonlarini tostlangan holda ikkiga bo'ling. Ichki qismiga bo'me'yorda ko'katli sous surting.\"}, {\"text\": \"Bottom nonlar ustiga tuxum, pishloq qo'yib, pechda pishloq eriguncha 5 daqiqa isiting. Ustiga qovurilgan piyoz qo'yib, ikkinchi non bilan yoping.\"}]", "is_published": true}, {"title": "Javdar Unli Qo'sh Shokoladli Pechenye (Double Chocolate Rye Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 30, "difficulty": "o'rtacha", "description": "Eritilgan achchiq shokolad, javdar uni va yong'oq bo'laklari solinib pishiriladigan qo'sh shokoladli pechenye.", "ingredients": "[{\"name\": \"90 g gretskiy yong'og'i (qovurilgan va to'g'ralgan)\\\\n255 g achchiq shokolad (bittersweet chocolate)\\\\n170 g shirin bo'lmagan shokolad (unsweetened chocolate)\\\\n115 g saryog'\\\\nYarim choy qoshiq vanil ekstrakti\\\\n300 g shakar\\\\n4 dona tuxum\\\\n60 g javdar uni (rye flour)\\\\nYarim choy qoshiq qabartma kukun (Razrixlitel)\\\\nYarim choy qoshiq tuz\"}]", "steps": "[{\"text\": \"140 g achchiq shokolad va 110 g shirin bo'lmagan shokoladni saryog' bilan bug' hammomida eritib sovuting. Vanilni qo'shing.\"}, {\"text\": \"Mikserda shakar va tuxumlarni 5 daqiqa davomida quyuq va och rang bo'lguncha ko'pirtiring. Eritilgan shokoladli saryog'ni qo'shib aralashtiring.\"}, {\"text\": \"Qolgan shokoladlarni yirik va mayda bo'laklarga bo'me'yorda to'g'rang.\"}, {\"text\": \"Javdar uni, qabartma kukun (Razrixlitel), tuz, yong'oq va shokolad bo'laklarini aralashtirib, tuxumli massaga spatula bilan buklab aralashtiring.\"}, {\"text\": \"Xamirni idishga solib, kamida 3–4 soat muzlatgichda sovuting.\"}, {\"text\": \"Pechni 175°C ga qizdiring. Xamirdan 2 osh qoshiqlik shariklar ajratib, listga 5 cm masofada tizib chiqing.\"}, {\"text\": \"175°C pechda 10–12 daqiqa chetlari tillarang bo'lguncha pishiring. Sim panjarada sovutib dasturxonga torting.\"}]", "is_published": true}, {"title": "Javdar Unli va Hamirturushli Brauni (Sourdough Rye Brownies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "O'ziga xos achigan javdar hamirturushi, to'q achchiq shokolad va saryog'dan pishiriladigan quyuq brauni.", "ingredients": "[{\"name\": \"1-bosqich (Hamirturush uchun):\\\\n72 g javdar uni\\\\n57 ml suv\\\\n36 g javdar hamirturushi (sourdough starter)\\\\n2-bosqich:\\\\n194 g javdar uni\\\\n3-bosqich (Brauni uchun):\\\\n5 dona tuxum\\\\n100 g shakar\\\\n195 g saryog'\\\\n475 g achchiq shokolad (kamida 66% kakao)\\\\n77 g shakar\\\\n265 g jigarrang shakar\\\\n70 g kakao kukuni\\\\n5 ml vanil ekstrakti\\\\n3 g soda\\\\n2 g tuz\"}]", "steps": "[{\"text\": \"1-bosqich masalliqlarini idishda aralashtirib, ustini yopib iliq joyda 4–6 soatga tindiring.\"}, {\"text\": \"1-bosqichdagi hamirturushdan 125 g ajratib oling va 194 g javdar uni bilan aralashtirib, 1–2 soat iliq joyda qoldiring.\"}, {\"text\": \"Saryog' va shokoladni issiq suvli qozoncha ustiga idish qo'yib (suv tegmaydigan qilib) eritib oling va 30 daqiqa sovuting. Pechni 160°C ga qizdiring. 25x25 cm qolipga pergament qog'oz soling.\"}, {\"text\": \"Tayyor xamirga eritilgan shokolad, saryog', tuxum, ikkala shakar, kakao, vanil, soda va tuzni solib mikserda yaxshilab ko'pirtiring.\"}, {\"text\": \"Massani qolipga quyib, 160°C pechda 30–40 daqiqa pishiring (usti quruq, o'rtasi biroz yumshoq bo'lishi kerak). Sovutib, bo'laklarga bo'ling.\"}]", "is_published": true}, {"title": "Limonli va Meringali Pirog (Lemon Meringue Pie)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Qarsildoq korj, nordon-shirin limonli zavarnoy kurd va momiq meringa kremi bilan pishiriladigan klassik pirog.", "ingredients": "[{\"name\": \"Korj uchun:\\\\n1 dona tayyor pirog korji\\\\nKrem (Kurd) uchun:\\\\n200 g shakar\\\\n5 osh qoshiq kraxmal\\\\nYarim choy qoshiq tuz\\\\n240 ml suv\\\\n120 ml sut\\\\n4 dona tuxum sarig'i\\\\n15 g saryog'\\\\n120 ml limon sharbati\\\\n2 choy qoshiq limon rendasi\\\\nMeringa (Krem) uchun:\\\\n4 dona tuxum oqi\\\\nYarim choy qoshiq limon kislotasi\\\\n100 g shakar\"}]", "steps": "[{\"text\": \"Pechni 200°C ga qizdiring. Korj xamirini qolipga yoyib, 10 daqiqa yopilgan holda, so'ng 12 daqiqa ochiq holda tillarang bo'lguncha pishirib sovuting. Pech haroratini 175°C ga tushiring.\"}, {\"text\": \"Qozonchada shakar, kraxmal va tuzni aralashtiring. Suv va sutni quyib ko'pirtiring. Tuxum sariqlarini qo'shib, o'rta olovda quyulguncha qaynatib oling.\"}, {\"text\": \"Olovdan olib saryog', limon sharbati va rendani solib aralashtiring.\"}, {\"text\": \"Meringa: Tuxum oqlarini limon kislotasi bilan mikserda ko'pirtiring. Shakarni oz-ozdan quyib, qattiq piklar hosil bo'lguncha davom eting.\"}, {\"text\": \"Issiq kremni korjga quying, ustiga meringa kremini tekis yoyib, sanchqi bilan cho'qqilar hosil qiling. 175°C pechda 15 daqiqa meringa tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Shokoladli Pudding Pirogi (Chocolate Pudding Pie)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Uvalanuvchan xamir korji, ipakdek shokoladli pudding va ko'pirtirilgan qaymoqli pirog.", "ingredients": "[{\"name\": \"Korj uchun:\\\\n155 g un\\\\n45 g sovuq saryog'\\\\n30 g o'simlik margarini (shortening)\\\\nYarim choy qoshiq tuz\\\\n3-4 osh qoshiq muzday suv\\\\nPudding uchun:\\\\n30 g kraxmal\\\\n90 g shakar\\\\n3 osh qoshiq kakao kukuni\\\\nYarim choy qoshiq tuz\\\\n700 ml sut\\\\n115 g achchiq shokolad (maydalangan)\\\\n1 choy qoshiq vanil\\\\nUstiga:\\\\n240 ml sovuq qaymoq\\\\n2 osh qoshiq shakar\"}]", "steps": "[{\"text\": \"Un, saryog', margarin va tuzni barmoqlar bilan ezib, kichik bo'lakchalar holiga keltiring. Muzday suv qo'shib xamirni to'plang va 1 soat muzlatgichda tindiring.\"}, {\"text\": \"Xamirni yoyib qolipga soling. 190°C pechda 35–40 daqiqa tillarang bo'lguncha pishirib sovuting.\"}, {\"text\": \"Qozonda kraxmal, 90 g shakar, kakao va tuzni aralashtiring. Sutni quyib, o'rta olovda 2 daqiqa qaynatib quyultiring. Olovdan olib shokolad va vanilni solib eriting.\"}, {\"text\": \"Puddingni sovigan korjga quyib, 2 soat muzlatgichda qotiring.\"}, {\"text\": \"Dasturxonga tortish oldidan qaymoq va 2 osh qoshiq shakarni ko'pirtirib, pirog ustini bezating.\"}]", "is_published": true}, {"title": "Mukammal Pishirilgan Pirog Xamiri (Blind-Baked Pie Crust)", "category": "Pishiriqlar & Xamirlar", "cook_time_minutes": 50, "difficulty": "oson", "description": "Shirin va tuzli piroglarning barchasi uchun mos keladigan uvalanuvchan va qarsildoq korj xamiri.", "ingredients": "[{\"name\": \"2 osh qoshiq shakar\\\\n2 choy qoshiq tuz\\\\n330 g un\\\\n340 g sovuq saryog' (kubik bo'lingan)\\\\n160 ml muzday suv\"}]", "steps": "[{\"text\": \"Katta idishda shakar, tuz va unni aralashtiring. Sovuq saryog'ni solib, barmoqlar bilan ezib yapaloq bo'lakchalar hosil qiling.\"}, {\"text\": \"Muzday suvni quyib, spatula bilan xamir holiga keltiring. Ikki bo'lakka bo'lib, har birini 1 soat muzlatgichda tindiring.\"}, {\"text\": \"Tindirilgan xamirni unlangan stolda yoyib, 23 cm diametrli pirog qolipiga joylashtiring va chetlariga shakl bering.\"}, {\"text\": \"Pechni 200°C ga qizdiring. Xamir ustiga pergament qog'oz solib, ustiga yuk (mosh yoki noxot) soling va 30–35 daqiqa pishiring.\"}, {\"text\": \"Yukni olib tashlab, pech haroratini 150°C ga tushiring va yana 10–15 daqiqa to'liq qarsildoq tillarang bo'lguncha pishiring.\"}]", "is_published": true}, {"title": "Bananli va Qaymoqli Pirog (Banana Cream Pie)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 40, "difficulty": "oson", "description": "Yangi banan parraklari, mayin zavarnoy krem va momiq qaymoq qatlami pishirig'i.", "ingredients": "[{\"name\": \"1 dona pishirilgan tayyor pirog korji\\\\n3 dona pishgan banan\\\\n400 ml sut\\\\n3 dona tuxum sarig'i\\\\n80 g shakar\\\\n3 osh qoshiq kraxmal\\\\n1 choy qoshiq vanil\\\\n200 ml ko'pirtirilgan qaymoq\"}]", "steps": "[{\"text\": \"Qozonda sut, tuxum sarig'i, shakar va kraxmalni silliq bo'lguncha ko'pirtirib, past olovda quyuq zavarnoy krem bo'lguncha pishiring. Olovdan olib vanilni solib sovuting.\"}, {\"text\": \"Bananlarni parrak qilib to'g'rang.\"}, {\"text\": \"Pishirilgan korj tubiga banan bo'laklarini bir tekis tizib chiqing.\"}, {\"text\": \"Ustidan sovigan zavarnoy kremni quying.\"}, {\"text\": \"Muzlatgichda 2 soat sovutgach, ustini ko'pirtirilgan qaymoq va banan bo'laklari bilan bezating.\"}]", "is_published": true}, {"title": "Kokos Sutida Dimlangan Ko'katlar (Coconut Creamed Greens)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 30, "difficulty": "oson", "description": "Ismaloq, kale va zanjabil-sarimsoqli ko'katlarning kokos sutida dimlangan xushbo'y garniri.", "ingredients": "[{\"name\": \"100 g kokos qiyg'ichi\\\\n1.3 kg har xil ko'katlar (kale\"}, {\"name\": \"mangold\"}, {\"name\": \"ispanoq)\\\\n60 ml kokos yog'i\\\\n6 tish sarimsoq (ezilgan)\\\\n1 dona piyoz (to'g'ralgan)\\\\n1 dona achchiq qizil qalampir\\\\n1 bo'lak (5 cm) zanjabil\\\\n1 osh qoshiq xardal urug'lari (mustard seeds)\\\\n2 choy qoshiq kashnich kukuni\"}, {\"name\": \"yarim choy qoshiq kurkuma\"}, {\"name\": \"tuz\\\\n480 ml kokos suti\\\\n50 g kashnich ko'kati\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Kokos qiyg'ichini listda 5–7 daqiqa qizartirib olib sovuting.\"}, {\"text\": \"Ko'katlarning qattiq tomirlarini olib tashlab, barglarini to'g'rang.\"}, {\"text\": \"Tovada kokos yog'ida sarimsoq, piyoz, qalampir va zanjabilni 5 daqiqa qovuring. Ziravorlarni solib 1 daqiqa qovurishda davom eting.\"}, {\"text\": \"Kokos sutini quyib qaynatib oling. Ko'katlarni oz-ozdan qo'shib, 15–18 daqiqa yumshaguncha dimlang.\"}, {\"text\": \"Ustiga qovurilgan kokos qiyg'ichlari va kashnich seping.\"}]", "is_published": true}, {"title": "Qovurilgan Shirin Kartoshka, Achchiq Asalli Saryog' va Laym (Charred Sweet Potatoes With Hot Honey Butter and Lime)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Pechda qizartirib pishirilgan batat kartoshkasi, asalli saryog' va qarsildoq qovoq urug'lari.", "ingredients": "[{\"name\": \"1.3 kg kichik shirin kartoshka (batat\"}, {\"name\": \"ikkiga bo'lingan)\\\\n120 ml zaytun yog'i\\\\nTuz\\\\n85 g saryog' (xonaki haroratda)\\\\n2 osh qoshiq asal\\\\n3 osh qoshiq achchiq sous (hot sauce)\\\\n30 g qovoq urug'lari (pepitas)\\\\n1 osh qoshiq kashnich kukuni\\\\nLaym bo'laklari\"}]", "steps": "[{\"text\": \"Pechni 220°C ga qizdiring. Shirin kartoshkalarni 60 ml zaytun yog'i va tuz bilan aralashtirib, kesilgan tarafini pastga qilib 25–30 daqiqa pechda pishiring.\"}, {\"text\": \"Idishda saryog', asal va achchiq sousni sanchqi bilan ko'pirtirib achchiq-asalli saryog' tayyorlang.\"}, {\"text\": \"Tovada qolgan 60 ml yog'da qovoq urug'larini 4 daqiqa qovuring, kashnich kukuni va tuz soling.\"}, {\"text\": \"Pishgan kartoshkalarni laganga tizib, ustiga asalli saryog' surting. Ustidan qovoq urug'li yog'ni quyib, laym sharbati siqib torting.\"}]", "is_published": true}, {"title": "Bodomli Rangli Pechenye (Pastel Butter Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Maydalangan bodom, saryog' va tabiiy mevali shakar kukuniga botiriladigan rang-barang pechenyelar.", "ingredients": "[{\"name\": \"140 g qovurilgan bodom\\\\n250 g un\\\\nYarim choy qoshiq tuz\\\\nYarim choy qoshiq dolchin\\\\n225 g saryog' (xonaki haroratda)\\\\n120 g shakar kukuni (+ har bir rang uchun 60 g shakar kukuni)\\\\n1 choy qoshiq vanil\\\\nQuritilgan mevalar (qulupnay\"}, {\"name\": \"chernika\"}, {\"name\": \"mango - maydalangan)\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Kombaynda bodom, un, tuz va dolchinni maydalang.\"}, {\"text\": \"Idishda saryog' va 120 g shakar kukunini 4 daqiqa ko'pirtiring. Vanil va bodomli un aralashmasini qo'shib xamir qoring.\"}, {\"text\": \"Xamirdan 1 osh qoshiqlik shariklar yasab, listga tizing va 175°C pechda 14–16 daqiqa pishirib sovuting.\"}, {\"text\": \"Har bir quritilgan meva va shakar kukunini kombaynda ko'pirtirib rangli shakar kukuni tayyorlang.\"}, {\"text\": \"Sovigan pechenyelarni rangli shakar kukunlariga botirib oling.\"}]", "is_published": true}, {"title": "Eroncha Guruch Unli Pechenye (Iranian Rice Cookies)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Guruch uni, gulob va hil aromati bilan pishiriladigan sharqona uvalanuvchan pechenye.", "ingredients": "[{\"name\": \"170 g saryog' (tovada biroz qizartirib eritilgan)\\\\n50 g shakar\\\\nChorak choy qoshiq gulob (rose water)\\\\n1 dona tuxum sarig'i\\\\n60 g un\\\\n100 g guruch uni\\\\nYarim choy qoshiq kardamon (hil)\\\\nYarim choy qoshiq tuz\"}]", "steps": "[{\"text\": \"Saryog'ni tovada qizartirib eritib, elakdan o'tkazing va sovuting.\"}, {\"text\": \"Idishda shakar va 2 osh qoshiq issiq suvni eriting. Gulob va tuxum sarig'ini solib ko'pirtiring, eritilgan saryog'ni oz-ozdan quyib aralashtiring.\"}, {\"text\": \"Alohida idishda ikki xil un, hil va tuzni aralashtiring. Saryog'li massaga qo'shib xamir qoring.\"}, {\"text\": \"Xamirdan sharikchalar yasab, listga tizing va sanchqi bilan yassilang.\"}, {\"text\": \"175°C pechda 16–18 daqiqa pishirib sovuting.\"}]", "is_published": true}, {"title": "Shirin Kartoshka, Kale va Nohotli Bouli (Sweet Potato Bowls With Kale and Chickpeas)", "category": "Garnirlar & Yengil Taomlar", "cook_time_minutes": 25, "difficulty": "oson", "description": "Dimlangan shirin kartoshka, nohot, karri va kokos sutida pishirilgan kale ko'kati solingan to'quvchi bowl.", "ingredients": "[{\"name\": \"450 g shirin kartoshka (batat\"}, {\"name\": \"kubik to'g'ralgan)\\\\n180 ml sabzavot bulyoni\\\\n300 ml kokos suti\\\\n1 osh qoshiq karri kukuni\\\\n220 g kale ko'kati (to'g'ralgan)\\\\n1 banka (400 g) konservalangan nohot\\\\n2 osh qoshiq limon sharbati\"}, {\"name\": \"tuz\"}, {\"name\": \"murch\\\\n300 g pishirilgan guruch\"}]", "steps": "[{\"text\": \"Qozonda shirin kartoshka va bulyonni 5 daqiqa qaynatib dimlang.\"}, {\"text\": \"Idishda kokos suti va karri kukunini aralashtiring.\"}, {\"text\": \"Qozonga kale ko'kati, nohot va kokos sutli aralashmani solib, qopqog'ini yopgan holda 8 daqiqa sekin qaynatib pishiring.\"}, {\"text\": \"Limon sharbati, tuz va murch solib aralashtiring.\"}, {\"text\": \"Idishlarga pishgan guruchni solib, ustidan kartoshkali va nohotli taomni quying.\"}]", "is_published": true}, {"title": "Shokoladli va Fundukli Pirog (Black-Bottom Hazelnut Pie)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Korj tubiga surtilgan erigan achchiq shokolad, qovurilgan funduk yong'og'i va qahvali pirog.", "ingredients": "[{\"name\": \"Korj uchun:\\\\n155 g un\\\\n115 g sovuq saryog'\\\\n1 choy qoshiq shakar\\\\nYarim choy qoshiq tuz\\\\n2-3 osh qoshiq muzday suv\\\\nIchlik uchun:\\\\n400 g funduk yong'og'i (hazelnuts)\\\\n115 g achchiq shokolad (eritilgan)\\\\n85 g saryog'\\\\n200 g jigarrang shakar\\\\n1 osh qoshiq qahva kukuni (espresso)\\\\n1 osh qoshiq vanil\\\\n300 ml makkajo'xori siropi (yoki asal)\\\\n1 choy qoshiq tuz\\\\n3 dona tuxum\"}]", "steps": "[{\"text\": \"Korj masalliqlaridan xamir qorib, 1 soat muzlatgichda tindiring. Yoyib qolipga soling va sovuting.\"}, {\"text\": \"Funduklarni 175°C pechda 10 daqiqa qovurib oling. 1 stakan butun fundukni bezak uchun ajratib, qolganini maydalang.\"}, {\"text\": \"Eritilgan shokoladni korj tubiga tekis yoyib, 15 daqiqa muzlatgichda qotiring.\"}, {\"text\": \"Idishda eritilgan saryog', jigarrang shakar, qahva kukuni, vanil, asal, tuz va tuxumlarni ko'pirtiring. Maydalangan fundukni qo'shing.\"}, {\"text\": \"Aralashmani korjga quyib, ustini butun funduklar bilan bezating. 175°C pechda 40–45 daqiqa pishirib sovuting.\"}]", "is_published": true}, {"title": "Zaytun Yog'li va Olmali Keks (Olive Oil Apple Cake with Spiced Sugar)", "category": "Pishiriqlar & Shirinliklar", "cook_time_minutes": 75, "difficulty": "o'rtacha", "description": "Zaytun yog'i, qirilgan shirin olmalar va xushbo'y dolchin-hil ziravorlari solib pishiriladigan keks.", "ingredients": "[{\"name\": \"240 ml zaytun yog'i\\\\n110 g shakar\\\\n2 dona nordon-shirin olma (qirilgan va suvi siqilgan)\\\\nZiravorlar: 1 choy qoshiq dolchin\"}, {\"name\": \"yarim choy qoshiq murch\"}, {\"name\": \"yarim choy qoshiq kardamon (hil)\"}, {\"name\": \"yarim choy qoshiq zanjabil\\\\n185 g un\\\\n2 choy qoshiq qabartma kukun (Razrixlitel)\\\\n2 dona tuxum + 2 dona tuxum sarig'i\\\\n100 g jigarrang shakar\\\\n1 choy qoshiq vanil\"}, {\"name\": \"yarim choy qoshiq tuz\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Qolipni zaytun yog'i va shakar bilan qoplang. Olmalarni qirib suvi qolmaguncha yaxshilab siqing.\"}, {\"text\": \"Barcha ziravorlarni aralashtiring. Chorak choy qoshig'ini ajratib, qolganiga un va qabartma kukun (Razrixlitel)ni qo'shib elang.\"}, {\"text\": \"Mikserda tuxumlar, jigarrang shakar, vanil, tuz va 100 g shakarni ko'pirtiring. Zaytun yog'ini quyib aralashtiring.\"}, {\"text\": \"Quruq masalliqlarni va qirilgan olmalarni qo'shib xamir holiga keltiring.\"}, {\"text\": \"Qolipga quyib, ustiga ajratilgan ziravor va 2 choy qoshiq shakar aralashmasini seping. 175°C pechda 60–70 daqiqa pishiring.\"}]", "is_published": true}, {"title": "Qarsildoq Qo'ziqorinli Qaymoqli Pasta", "category": "Garnirlar va Sabzavotli Taomlar", "cook_time_minutes": 25, "difficulty": "o'rtacha", "description": "Tillarang qarsildoq qo'ziqorinlar, spagetti, qaymoq, limon sharbati va parmezan pishlog'idan tayyorlanadigan mayin va xushbo'y pasta.", "ingredients": "[{\"name\": \"60 ml zaytun yog'i\\\\n450 g har xil qo'ziqorin (shampinyon\"}, {\"name\": \"veshenka)\\\\n1 choy qoshiq tuz\\\\n2 dona sharlot piyoz (mayda to'g'ralgan)\\\\n450 g spagetti\\\\n120 ml qaymoq\\\\nYarim dona limon sharbati va rendasi\\\\n30 g petrushka ko'kati\\\\n30 g saryog'\\\\n15 g parmezan pishlog'i (qirilgan)\\\\nQora murch\"}]", "steps": "[{\"text\": \"Tovada 30 ml yog'ni qizdirib, qo'ziqorinlarning yarmini 5 daqiqa tillarang va qarsildoq bo'lguncha qovurib oling. Tuz seping. Qolgan yog' va qo'ziqorinlar bilan ham shunday qiling.\"}, {\"text\": \"Olovni pasaytirib, barcha qo'ziqorinlarni tovaga qaytaring. Piyozni solib, 2 daqiqa yumshaguncha qovuring.\"}, {\"text\": \"Qozonda tuzli suvni qaynatib, spagettini pishirib oling (suvidan 240 ml olib qo'ying).\"}, {\"text\": \"Pishgan spagettini qo'ziqorinli tovaga soling. Qaymoq va 240 ml makaron suvidan quyib, o'rta olovda 3 daqiqa sous quyulguncha aralashtiring.\"}, {\"text\": \"Olovdan olib limon sharbati, rendasi, petrushka, saryog', parmezan pishlog'i va murch solib aralashtiring.\"}]", "is_published": true}, {"title": "Kuzgi Mevali Galetta", "category": "Piroglar va Tartlar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Ingichka kesilgan olma, fenxel urug'i, olma sirkasi va vanil bilan pishiriladigan qarsildoq frantsuzcha galetta.", "ingredients": "[{\"name\": \"2 choy qoshiq fenxel urug'i\\\\n1 choy qoshiq tuz\\\\n70 g shakar (+ sepish uchun)\\\\n900 g olma (ingichka parrak kesilgan)\\\\n1 osh qoshiq olma sirkasi\\\\n1 choy qoshiq vanil\\\\n1 dona tayyor galetta xamiri\\\\n1 osh qoshiq qaymoq\"}]", "steps": "[{\"text\": \"Pechni 200°C ga qizdiring. Fenxel urug'larini tovada 3 daqiqa qovurib maydalang.\"}, {\"text\": \"Idishda fenxel, tuz va 70 g shakarni aralashtiring. Olma bo'laklarini qo'shib aralashtiring. Sirka va vanilni soling.\"}, {\"text\": \"Xamirni pergament ustida yoyib, o'rtasiga olma aralashmasini tizib chiqing (chetlaridan 7 cm joy qoldiring).\"}, {\"text\": \"Xamir chetlarini olmalar ustiga buking. Ustiga qaymoq surtib, shakar seping.\"}, {\"text\": \"Pech haroratini 190°C ga tushirib, 45–50 daqiqa tillarang bo'lguncha pishiring. 2 soat sovutib torting.\"}]", "is_published": true}, {"title": "Qarsildoq Pirog Xamiri", "category": "Piroglar va Tartlar", "cook_time_minutes": 20, "difficulty": "oson", "description": "Har qanday shirin va tuzli piroglar uchun kat-kat va o'ta qarsildoq universal xamir tayyorlash retsepti.", "ingredients": "[{\"name\": \"1.5 choy qoshiq shakar\\\\nChorak choy qoshiq tuz\\\\n180 g un\\\\n170 g sovuq saryog' (bo'lingan)\\\\n60 ml muzday suv\"}]", "steps": "[{\"text\": \"Idishda shakar, tuz va unni aralashtiring. Sovuq saryog'ni unga belang va stolda juvala bilan ezib ingichka bo'lakchalar holiga keltiring.\"}, {\"text\": \"Aralashmaga 60 ml muzday suv quyib, xamir holiga keltiring.\"}, {\"text\": \"Xamirni to'rtburchak qilib yoyib, xat konvertidek uchga taxlang. Bu jarayonni 3 marta takrorlang (kat-kat bo'lishi uchun).\"}, {\"text\": \"Xamirni plyonkaga o'rab, 30 daqiqa muzlatgichda tindiring. Yoyib piroglarga ishlatishingiz mumkin.\"}]", "is_published": true}, {"title": "Shokoladli Super Tort", "category": "Tortlar va Chizkeyklar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Eritilgan achchiq shokolad, qatiqli xamir va maxsus shokoladli saryog'li krem bilan boyitilgan afsonaviy shokoladli tort.", "ingredients": "[{\"name\": \"Xamir uchun:\\\\n240 g saryog' (xonaki haroratda)\\\\n300 g un\"}, {\"name\": \"50 g kakao kukuni\"}, {\"name\": \"1.5 choy qoshiq qabartma kukun (Razrixlitel)\"}, {\"name\": \"yarim choy qoshiq soda\"}, {\"name\": \"yarim choy qoshiq tuz\\\\n400 ml qatiq\"}, {\"name\": \"2 choy qoshiq vanil\"}, {\"name\": \"450 g jigarrang shakar\"}, {\"name\": \"3 dona tuxum\\\\n225 g achchiq shokolad (eritilgan)\\\\nKrem uchun:\\\\n140 g saryog'\"}, {\"name\": \"120 g shakar kukuni\"}, {\"name\": \"115 g achchiq shokolad (eritilgan va sovutilgan)\"}, {\"name\": \"2 osh qoshiq soya sousi\"}, {\"name\": \"1 choy qoshiq vanil\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. 23x33 cm qolipni yog'lang.\"}, {\"text\": \"Idishda un, kakao, qabartma kukun (Razrixlitel), soda va tuzni elang.\"}, {\"text\": \"Mikserda 240 g saryog' va jigarrang shakarni 2 daqiqa ko'pirtiring. Tuxumlarni bittalab qo'shing.\"}, {\"text\": \"Unli aralashma va qatiqni navbatma-navbat qo'shib aralashtiring. Eritilgan shokoladni soling.\"}, {\"text\": \"Qolipga quyib, 175°C pechda 40 daqiqa pishiring va 2 soat sovuting.\"}, {\"text\": \"Krem: Mikserda saryog'ni ko'pirtiring. Shakar kukuni, eritilgan shokolad, soya sousi va vanilni qo'shib 30 soniya ko'pirtiring. Sovigan tort ustiga surting.\"}]", "is_published": true}, {"title": "Shirin Kartoshkali Noshtabop Boul", "category": "Nonushta va Pishiriqlar", "cook_time_minutes": 50, "difficulty": "oson", "description": "Pechda pishirilgan shirin kartoshka (batat) pyuresi, qarsildoq bekon, chernika mevalari, banan va bodomli energiya manbai.", "ingredients": "[{\"name\": \"900 g shirin kartoshka (batat)\\\\n225 g bekon\\\\n30 ml kokos suti\\\\n1 choy qoshiq vanil\\\\nBir chimdim tuz\\\\n150 g chernika\\\\n1 dona pishgan banan\\\\n30 g to'g'ralgan bodom\"}]", "steps": "[{\"text\": \"Pechni 200°C ga qizdiring. Shirin kartoshkalarni pergamentli listda 45 daqiqa pechda pishirib sovuting. Bekonni ham pechda qizartirib pishiring va to'g'rang.\"}, {\"text\": \"Shirin kartoshka po'stini archib, mag'zini kombaynga soling. Kokos suti, vanil va tuz qo'shib 30 soniya silliq pyure bo'lguncha ezib oling.\"}, {\"text\": \"Pyureni idishlarga solib, ustidan to'g'ralgan bekon, chernika, banan va bodom bo'laklarini qo'yib dasturxonga torting.\"}]", "is_published": true}, {"title": "Muzlatilgan Margarita Pirogi", "category": "Piroglar va Tartlar", "cook_time_minutes": 20, "difficulty": "oson", "description": "Kreker korji ustidagi nordon-shirin laym, ko'pirtirilgan qaymoq va quyultirilgan sutli salqin muzlatilgan pirog.", "ingredients": "[{\"name\": \"Korj uchun:\\\\n85 g saryog'\"}, {\"name\": \"10 dona grek krekeri uvoqlari\"}, {\"name\": \"40 g shakar\"}, {\"name\": \"chorak choy qoshiq tuz\\\\nKrem uchun:\\\\n180 ml sovuq qaymoq\"}, {\"name\": \"4 dona laym sharbati (120 ml) va rendasi\"}, {\"name\": \"1 banka (400 g) quyultirilgan sut (kondensirovannoye moloko)\"}, {\"name\": \"3 osh qoshiq tekila (xohishga ko'ra)\"}]", "steps": "[{\"text\": \"Kreker uvoqlari, eritilgan saryog', shakar va tuzni aralashtirib pirog qolipiga presslang. 20 daqiqa muzlatgichda qotiring.\"}, {\"text\": \"Mikserda qaymoqni quyuq bo'lguncha ko'pirtiring.\"}, {\"text\": \"Idishda laym sharbati, quyultirilgan sut, tekila va tuzni aralashtiring. Ko'pirtirilgan qaymoqni ohista qo'shib spatula bilan aralashtiring.\"}, {\"text\": \"Kremni korj ustiga quyib, laym rendasi seping. Muzlatgichda kamida 8 soat muzlating.\"}]", "is_published": true}, {"title": "Reyhanli Saryog'li Makkajo'xori", "category": "Garnirlar va Sabzavotli Taomlar", "cook_time_minutes": 25, "difficulty": "oson", "description": "Olovda qizartirib pishirilgan xushbo'y rayhon va timyanli saryog' surtilgan shirin makkajo'xori so'talari.", "ingredients": "[{\"name\": \"1.5 osh qoshiq to'g'ralgan reyhan (basil)\\\\nYarim choy qoshiq timyan\\\\n85 g saryog' (yumshatilgan)\\\\n8 so'ta makkajo'xori\\\\nTuz\"}]", "steps": "[{\"text\": \"Yumshoq saryog'ga to'g'ralgan reyhan va timyanni solib aralashtiring.\"}, {\"text\": \"Makkajo'xori so'talarini olovda yoki tovada 15–18 daqiqa har bir tarafini qizartirib pishirib oling.\"}, {\"text\": \"Issiq makkajo'xorilarga reyhanli saryog' surtib, tuz seping va issiq holda torting.\"}]", "is_published": true}, {"title": "Xallumi Pishloqli va Shirin Kartoshkali Burger", "category": "Go'sht va Parranda Taomlari", "cook_time_minutes": 40, "difficulty": "o'rtacha", "description": "Shirin kartoshka va kale kotleti, qizartirilgan Xallumi pishloq bo'lagi va ezilgan avokado bilan tayyorlanadigan foydali burger.", "ingredients": "[{\"name\": \"500 g shirin kartoshka (batat)\\\\n175 g kale ko'kati (to'g'ralgan)\\\\n1 osh qoshiq zaytun yog'i\\\\n8 dona yashil piyoz\"}, {\"name\": \"2 tish sarimsoq\"}, {\"name\": \"1 dona achchiq qizil qalampir\"}, {\"name\": \"kashnich\\\\n2 osh qoshiq un\"}, {\"name\": \"50 g kunchut\\\\n250 g xallumi pishlog'i (bo'laklangan)\\\\n4 dona burger noni\"}, {\"name\": \"1 dona pishgan avokado (ezilgan)\"}, {\"name\": \"tuz\"}, {\"name\": \"murch\"}]", "steps": "[{\"text\": \"Shirin kartoshkani suvda 15 daqiqa qaynatib ezib oling. Kale ko'katini 4 daqiqa qaynatib to'g'rang.\"}, {\"text\": \"Tovada yashil piyoz, sarimsoq va qalampirni 2-3 daqiqa qovuring. Kashnich soling.\"}, {\"text\": \"Idishda kartoshka, kale, qovurilgan sabzavotlar, un, tuz va murch bilan kotlet xamiri tayyorlang. 4 ta burger shaklini berib, kunchutga bulang va 30 daqiqa muzlatgichda tindiring.\"}, {\"text\": \"Kotletlarni tovada 3–4 daqiqa har bir tarafini qizartirib qovuring.\"}, {\"text\": \"Xallumi pishlog'ini quruq tovada 2 daqiqa qizartirib oling.\"}, {\"text\": \"Burger nonlariga ezilgan avokado surtib, kotlet va xallumi pishlog'ini qo'yib yoping.\"}]", "is_published": true}, {"title": "Oq Shaftoli va Vanilli Muzqaymoq", "category": "Muzqaymoq va Sovuq Desertlar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Pishirilgan oq shaftoli pyuresi, vanilli sut va tuxum sarig'i kremidan tayyorlanadigan tabiiy uy muzqaymog'i.", "ingredients": "[{\"name\": \"1 litr suv\"}, {\"name\": \"330 g shakar\\\\n1.2 kg oq shaftoli\\\\n500 ml sut\"}, {\"name\": \"250 ml qaymoq\"}, {\"name\": \"1 choy qoshiq vanil\\\\n8 dona tuxum sarig'i\"}, {\"name\": \"150 g shakar\\\\n60 ml burbon (yoki xohishga ko'ra sirop)\"}]", "steps": "[{\"text\": \"Qozonda suv va 330 g shakarni eritib qaynating. Shaftolilarni solib 15–20 daqiqa qaynatib yumshating. Archib, yarmini blenderda ezib pyure qiling, yarmini sovutib qo'ying.\"}, {\"text\": \"Qozonchada sut, qaymoq va vanilni qaynash darajasiga keltiring.\"}, {\"text\": \"Idishda tuxum sariqlari va 150 g shakarni ko'pirtiring. Issiq sutli aralashmani quyib ko'pirtiring va past olovda 8 daqiqa quyulguncha pishirib sovuting.\"}, {\"text\": \"Kremga shaftoli pyuresi va burbonni aralashtiring. Qolipga quyib 8 soat muzlatgichda muzlating.\"}, {\"text\": \"Muzqaymoqni bo'laklab blenderda bir marta ko'pirtirib, yana 1 soat qotiring. Pishgan shaftolilar bilan torting.\"}]", "is_published": true}, {"title": "Qovun, Noxot Dukkagi va Rikotta Salati", "category": "Salatlar", "cook_time_minutes": 15, "difficulty": "oson", "description": "Shirin qovun parraklari, qarsildoq noxot dukkagi, rikotta pishlog'i va estragon bargli tetiklashtiruvchi salat.", "ingredients": "[{\"name\": \"700 g shirin qovun (ingichka parrak qilingan)\\\\n225 g shirin noxot dukkagi (ingichka to'g'ralgan)\\\\n225 g rikotta pishlog'i (yoki sho'r pishloq bo'laklari)\\\\n3 osh qoshiq estragon barglari\\\\nZaytun yog'i\"}, {\"name\": \"limon sharbati\"}, {\"name\": \"tuz\"}, {\"name\": \"achchiq murch\"}]", "steps": "[{\"text\": \"Qovun po'stini archib, ingichka parraklarga bo'ling.\"}, {\"text\": \"Laganda qovun bo'laklari, noxot dukkaklari, pishloq va estragon barglarini aralashtiring.\"}, {\"text\": \"Ustidan zaytun yog'i, limon sharbati, tuz va achchiq murch seping.\"}]", "is_published": true}, {"title": "Avokado va Yer-yong'oq Pishlog'li Brauni", "category": "Pechenye va Biskvitlar", "cook_time_minutes": 45, "difficulty": "oson", "description": "Avokado, yer-yong'oq pastasi, kakao va suli unidan tayyorlanadigan tabiiy shirin va parhezbop brauni.", "ingredients": "[{\"name\": \"2 dona avokado\\\\n2 dona tuxum (biroz ko'pirtirilgan)\\\\n30 ml kokos yog'i (eritilgan)\\\\n120 ml klyon siropi (yoki asal)\\\\n1 choy qoshiq vanil\\\\n30 g vanilli protein kukuni (yoki qatqaloq un)\\\\n60 g suli uni yoki bodom uni\\\\n25 g kakao kukuni\\\\nYarim choy qoshiq qabartma kukun (Razrixlitel)\\\\nChorak choy qoshiq tuz\\\\n30 g yer-yong'oq pastasi (peanut butter)\"}]", "steps": "[{\"text\": \"Pechni 175°C ga qizdiring. Pishirish qolipiga yog' surting.\"}, {\"text\": \"Chuqur idishda avokado, tuxum, kokos yog'i, klyon siropi va vanilni mikserda silliq bo'lguncha ko'pirtiring.\"}, {\"text\": \"Alohida idishda suli uni, protein kukuni, kakao, qabartma kukun (Razrixlitel) va tuzni aralashtiring.\"}, {\"text\": \"Suyuq va quruq masalliqlarni birlashtirib yumshoq xamir qoring va qolipga quying.\"}, {\"text\": \"Ustiga yer-yong'oq pastasidan tomizib, pichoq bilan aralashtirib naqsh hosil qiling.\"}, {\"text\": \"175°C pechda 30–35 daqiqa pishiring.\"}]", "is_published": true}, {"title": "Kartoshka va Xardal Bargli Tart", "category": "Piroglar va Tartlar", "cook_time_minutes": 70, "difficulty": "o'rtacha", "description": "Qat-kat filo xamiri tubida ingichka kartoshka parraklari, xardal barglari (yoki ispanoq), echki pishlog'i va tuxumli sous.", "ingredients": "[{\"name\": \"4 varaq qat-kat xamir (filo xamiri)\\\\n1 dona katta kartoshka (ingichka parrak qilingan)\\\\n120 ml qatiq (yoki buttermilk)\\\\nTuz va qora murch\\\\n15 ml o'simlik yog'i\\\\n1 dona piyoz (to'g'ralgan)\\\\n150 g xardal barglari (yoki ispanoq)\\\\n2 dona tuxum + 3 dona tuxum oqi\\\\n120 ml yog'siz sut\\\\n2 choy qoshiq timyan\\\\n60 g echki pishlog'i (yoki brynza/feta)\"}]", "steps": "[{\"text\": \"Pechni 190°C ga qizdiring. Tart qolipiga filo xamirini yoying.\"}, {\"text\": \"Idishda ingichka kesilgan kartoshkalarni qatiq, tuz va murch bilan aralashtiring.\"}, {\"text\": \"Tovada yog'ni qizdirib, piyozni 2 daqiqa qovuring. Xardal barglarini solib, 5 daqiqa yumshaguncha qovuring.\"}, {\"text\": \"Qolip tubiga kartoshka parraklarining yarmini va ko'katlarning yarmini tizib chiqing. Qolgan kartoshka va ko'katlarni ikkinchi qatlam qilib soling.\"}, {\"text\": \"Idishda tuxumlar, tuxum oqlari, sut, timyan, tuz va murch ko'pirtirilib, kartoshkalar ustidan quyiladi. Ustiga pishloq bo'laklari solinadi.\"}, {\"text\": \"190°C pechda 45–60 daqiqa kartoshkalar pishguncha pishiring. 15 daqiqa sovutib kasing.\"}]", "is_published": true}, {"title": "Shirin Kartoshka va Nohotli Budda Bouli", "category": "Garnirlar va Sabzavotli Taomlar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Pechda pishirilgan shirin kartoshka (batat), qarsildoq ziravorli noxot, kinoa hamda bulg'ori va kunchutli taxini sousli boul.", "ingredients": "[{\"name\": \"Sous uchun:\\\\n1 dona bulg'ori murchi (to'g'ralgan)\"}, {\"name\": \"1 tish sarimsoq\"}, {\"name\": \"60 g taxini (kunchut pastasi)\"}, {\"name\": \"3 osh qoshiq limon sharbati\"}, {\"name\": \"1 osh qoshiq zaytun yog'i\"}, {\"name\": \"tuz\"}, {\"name\": \"murch\"}, {\"name\": \"60 ml suv\\\\nAsosiy taom uchun:\\\\n200 g kinoa (yoki guruch)\"}, {\"name\": \"700 g shirin kartoshka (batat\"}, {\"name\": \"kubik kesilgan)\"}, {\"name\": \"1.5 osh qoshiq kokos yog'i\"}, {\"name\": \"2 choy qoshiq klyon siropi\"}, {\"name\": \"1 choy qoshiq apelsin rendasi\\\\nQovurilgan nohot va ko'kat uchun:\\\\n1 banka (400 g) nohot\"}, {\"name\": \"1 osh qoshiq zaytun yog'i\"}, {\"name\": \"paprika\"}, {\"name\": \"kumin\"}, {\"name\": \"achchiq murch\"}, {\"name\": \"tuz\"}, {\"name\": \"1 bog' mangold ko'kati (yoki ispanoq)\"}, {\"name\": \"4 tish sarimsoq\"}]", "steps": "[{\"text\": \"Blenderda bulg'ori murchi, sarimsoq, taxini, limon sharbati, zaytun yog'i, 60 ml suv, tuz va murch ko'pirtirilib, silliq sous tayyorlanadi.\"}, {\"text\": \"Pechni 215°C ga qizdiring. Kinoani (yoki guruchni) suvda pishirib oling.\"}, {\"text\": \"Shirin kartoshkani eritilgan kokos yog'i, klyon siropi, apelsin rendasi va tuz bilan aralashtirib, listda 30-35 daqiqa pechda pishiring.\"}, {\"text\": \"Nohotni zaytun yog'i, paprika, kumin, achchiq murch va tuz bilan aralashtirib, listda kartoshka bilan birga 15-20 daqiqa qarsildoq bo'lguncha pishiring.\"}, {\"text\": \"Tovada yog'da sarimsoq va achchiq murch qovuriladi, mangold ko'kati solinib 3-4 daqiqa dimlanadi.\"}, {\"text\": \"Idishlarga pishgan kinoa, shirin kartoshka, qarsildoq nohot va ko'katlar solinib, ustidan taxini sousi quyib tortiladi.\"}]", "is_published": true}, {"title": "Shirin Kartoshka, Qiymali Qo'y Go'shti va Qo'ziqorinli Bouli", "category": "Go'sht va Parranda Taomlari", "cook_time_minutes": 35, "difficulty": "o'rtacha", "description": "Bug'da pishirilgan ezilgan shirin kartoshka, xushbo'y ziravorli qo'y go'shti qiymasi, qo'ziqorin va limonli yogurtli sous.", "ingredients": "[{\"name\": \"1 dona katta shirin kartoshka (batat)\\\\nYarim dona fenxel (ingichka to'g'ralgan)\\\\nYarim dona qizil piyoz (ingichka to'g'ralgan)\\\\n60 ml olma sirkasi\"}, {\"name\": \"45 ml zaytun yog'i\\\\n225 g qo'y go'shti qiymasi\\\\n1 choy qoshiq kumin\"}, {\"name\": \"yarim choy qoshiq dolchin\"}, {\"name\": \"1 choy qoshiq achchiq murch\"}, {\"name\": \"tuz\\\\n225 g qo'ziqorin (to'g'ralgan)\\\\n120 g yogurt\"}, {\"name\": \"2 osh qoshiq limon sharbati\"}, {\"name\": \"Yalpiz barglari\"}]", "steps": "[{\"text\": \"Qozonda bug'da shirin kartoshkani 20–25 daqiqa yumshaguncha pishirib oling.\"}, {\"text\": \"Idishda fenxel, qizil piyoz, sirka va tuzni aralashtirib 15 daqiqa marinatlang.\"}, {\"text\": \"Tovada 2 osh qoshiq yog'da qo'y go'shti qiymasi, kumin, dolchin, murch va tuzni 4 daqiqa qizartirib qovuring. Qo'ziqorinlarni solib, yana 5 daqiqa birga qovuring.\"}, {\"text\": \"Kichik idishda yogurt, limon sharbati, 1 osh qoshiq yog' va tuzni ko'pirtirib sous tayyorlang.\"}, {\"text\": \"Shirin kartoshkani teng ikkiga bo'lib idishlarga soling va sanchqi bilan ezib yassilang. Ustiga yogurt sousi, qiyma va qo'ziqorinli aralashma, marinatlangal piyoz va yalpiz qo'yib torting.\"}]", "is_published": true}, {"title": "Olmali va Kalvadosli Frantsuzcha Galetta", "category": "Piroglar va Tartlar", "cook_time_minutes": 60, "difficulty": "o'rtacha", "description": "Olmali pyure ustiga qat-qat tizilgan yangi olma bo'laklari, saryog' va kalvadosli ko'pirtirilgan qaymoq bilan tortiladigan galetta.", "ingredients": "[{\"name\": \"1 dona tayyor galetta xamiri\\\\n800 g gala olmasi (ingichka parrak kesilgan)\\\\n2 choy qoshiq limon sharbati\\\\n70 g shakar (+ 10 g sepish uchun)\\\\n200 g olmali sous (applesauce)\\\\n45 g saryog'\\\\n2 osh qoshiq olma djem/jem\\\\n240 ml sovuq qaymoq\\\\n1 osh qoshiq shakar kukuni\\\\n2 osh qoshiq kalvados (yoki olma sharbati/likyor)\"}]", "steps": "[{\"text\": \"Pechni 220°C ga qizdiring. Xamirni pergamentli listda yoying va 30 daqiqa muzlatgichda tindiring.\"}, {\"text\": \"Olmalarni archib ingichka kesing. Limon sharbati va 70 g shakar bilan aralashtiring.\"}, {\"text\": \"Xamir ustiga olmali sousni surting (chetlaridan 5 cm joy qoldiring). Ustiga olma bo'laklarini tizib chiqing.\"}, {\"text\": \"Xamir chetlarini olmalar ustiga buking. Ustiga saryog' bo'lakchalarini qo'yib, xamir chetlariga 10 g shakar seping.\"}, {\"text\": \"220°C pechda 40–45 daqiqa tillarang bo'lguncha pishiring.\"}, {\"text\": \"Pishgach, ustiga eritilgan olma djemini surting.\"}, {\"text\": \"Mikserda qaymoq va shakar kukunini ko'pirtiring, kalvados qo'shing. Galettani kalvadosli qaymoq bilan torting.\"}]", "is_published": true}, {"title": "Tvorogli va Shokoladli Brauni Pechenye", "category": "Pechenye va Biskvitlar", "cook_time_minutes": 45, "difficulty": "o'rtacha", "description": "Quyuq brauni xamiri va o'rtasida tvorogli pishloq (cream cheese) va shokolad bo'laklaridan iborat krem mag'izli pechenye.", "ingredients": "[{\"name\": \"Brauni xamiri uchun:\\\\n225 g shakar\"}, {\"name\": \"80 g kakao kukuni\"}, {\"name\": \"150 g saryog'\"}, {\"name\": \"1 choy qoshiq tuz\"}, {\"name\": \"yarim choy qoshiq vanil\"}, {\"name\": \"2 dona sovuq tuxum\"}, {\"name\": \"65 g un\\\\nTvorogli mag'iz uchun:\\\\n115 g cream cheese (tvorogli pishloq)\"}, {\"name\": \"40 g shakar\"}, {\"name\": \"1.5 choy qoshiq kraxmal\"}, {\"name\": \"chimdim tuz\"}, {\"name\": \"40 g maydalangan achchiq shokolad\"}]", "steps": "[{\"text\": \"Idishda shakar, kakao, saryog' va tuzni issiq suvli qozoncha ustida saryog' eriguncha eritib olib, 5 daqiqa sovuting.\"}, {\"text\": \"Vanil va tuxumlarni bittalab qo'shib mikserda ko'pirtiring. Unni solib, yarqiragan xamir bo'lguncha 1 daqiqa aralashtiring. Ustini yopib 8 soat muzlatgichda sovuting.\"}, {\"text\": \"Mikserda cream cheese, shakar, kraxmal va tuzni ko'pirtiring. Maydalangan shokoladni qo'shing. Buni ham 8 soat muzlatgichda qotiring.\"}, {\"text\": \"Pechni 175°C ga qizdiring. Brauni xamiridan 20 dona sharik yasang. O'rtasini bosing va 1 choy qoshiqdan tvorogli krem solib, chetlarini yoping.\"}, {\"text\": \"Pergamentli listga tizib, 175°C pechda 12–14 daqiqa pishiring. Ustiga tuz seping.\"}]", "is_published": true}, {"title": "Shokoladli va Perezelli Konfetlar (Tryufel)", "category": "Shirinliklar", "cook_time_minutes": 30, "difficulty": "oson", "description": "Achchiq shokolad ganashi, maydalangan qarsildoq perezel krakeri va karamellangan shakarli qoplamali shohona tryufel.", "ingredients": "[{\"name\": \"180 ml qaymoq\\\\n600 g achchiq shokolad (maydalangan)\\\\n100 g qarsildoq perezel (maydalangan)\\\\nYarim choy qoshiq tuz\\\\n80 ml burbon (yoki xohishga ko'ra sirop)\\\\n220 g jigarrang shakar + 2 osh qoshiq burbon (shakarli qoplama uchun)\"}]", "steps": "[{\"text\": \"Qozonda qaymoqni qaynatib oling. Idishdagi maydalangan shokolad ustiga quying va issiq suvli qozoncha ustida eritib oling.\"}, {\"text\": \"Eritilgan shokoladga maydalangan perezel, tuz va 80 ml burbonni qo'shib aralashtiring. 2-3 soat muzlatgichda qotiring.\"}, {\"text\": \"Burbonli shakar: Pechni 160°C ga qizdiring. Jigarrang shakar va 2 osh qoshiq burbonni aralashtirib, listda 30 daqiqa qarsildoq bo'lguncha pishiring va sovutib maydalang.\"}, {\"text\": \"Qotgan shokoladli massadan choy qoshiq yordamida shariklar yasang va burbonli shakarga botirib oling. 30 daqiqa muzlatgichda qotiring.\"}]", "is_published": true}, {"title": "Kimchi va Yashil Piyozli Qarsildoq Pirojkalar", "category": "Nonushta va Pishiriqlar", "cook_time_minutes": 25, "difficulty": "o'rtacha", "description": "Muzday gazlangan suvli xamirdan tayyorlanadigan to'g'ralgan kimchi, yashil piyoz va maxsus soya sousli Koreyscha qarsildoq quymoqlar.", "ingredients": "[{\"name\": \"Sous uchun:\\\\n2 osh qoshiq soya sousi\"}, {\"name\": \"2 osh qoshiq guruch sirkasi\"}, {\"name\": \"yarim choy qoshiq kunchut yog'i\"}, {\"name\": \"yarim choy qoshiq shakar\"}, {\"name\": \"achchiq murch\"}, {\"name\": \"yashil piyoz\\\\nXamir va ichlik uchun:\\\\n125 g un\"}, {\"name\": \"60 g guruch uni\"}, {\"name\": \"yarim choy qoshiq tuz\"}, {\"name\": \"1 dona tuxum\"}, {\"name\": \"240 ml muzday gazlangan suv\"}, {\"name\": \"60 ml kimchi suvi\"}, {\"name\": \"150 g kimchi (to'g'ralgan)\"}, {\"name\": \"4 dona yashil piyoz\"}, {\"name\": \"1 dona achchiq qizil qalampir\"}, {\"name\": \"60 ml o'simlik yog'i\"}]", "steps": "[{\"text\": \"Idishda soya sousi, sirka, kunchut yog'i, shakar, murch va 2 osh qoshiq suvni aralashtirib sous tayyorlang.\"}, {\"text\": \"Katta idishda ikki xil un, tuz, tuxum, muzday gazlangan suv va kimchi suvini ko'pirtirib xamir qoring. To'g'ralgan kimchi, piyoz va qalampirni solib aralashtiring.\"}, {\"text\": \"Tovada 1 osh qoshiq yog'ni qizdiring. Yarim stakan xamirdan quyib, past-o'rta olovda 2-3 daqiqa har bir tarafini tillarang va qarsildoq bo'lguncha qovuring.\"}, {\"text\": \"Qolgan xamir va yog' bilan yana pirojkalar pishiring. Bo'laklab, sous bilan torting.\"}]", "is_published": true}, {"title": "Matcha Choyli va Bodomli Pechenye", "category": "Pechenye va Biskvitlar", "cook_time_minutes": 35, "difficulty": "oson", "description": "Bodom pastasi va unli xamir markazida xushbo'y matcha yashil choyi va shakar kukunli krem solingan yaponcha pechenye.", "ingredients": "[{\"name\": \"Pechenye uchun:\\\\n1.5 choy qoshiq tuxum o'rnini bosuvchi kukun (yoki 1 dona tuxum)\"}, {\"name\": \"150 g bodom pastasi\"}, {\"name\": \"120 ml agava siropi (yoki asal)\"}, {\"name\": \"75 g o'simlik saryog'i\"}, {\"name\": \"yarim choy qoshiq vanil\"}, {\"name\": \"yarim choy qoshiq bodom ekstrakti\"}, {\"name\": \"150 g un\"}, {\"name\": \"yarim choy qoshiq tuz\\\\nKrem uchun:\\\\n1 osh qoshiq matcha choy kukuni\"}, {\"name\": \"2 osh qoshiq suyuq qaymoq\"}, {\"name\": \"115 g o'simlik saryog'i\"}, {\"name\": \"350 g shakar kukuni\"}]", "steps": "[{\"text\": \"Pechni 165°C ga qizdiring. Listni yog'lang.\"}, {\"text\": \"Idishda bodom pastasi, agava siropi va saryog'ni krem holatiga kelguncha ko'pirtiring. Vanil, bodom ekstrakti, un va tuzni solib yumshoq xamir qoring.\"}, {\"text\": \"Xamirdan kichik shariklar yasab listga tizing. Barmog'ingiz bilan har bir pechenye o'rtasini bosing (chuqurcha hosil qiling).\"}, {\"text\": \"165°C pechda 15 daqiqa pishirib sovuting.\"}, {\"text\": \"Krem: Kichik idishda matcha kukuni va qaymoqni aralashtiring. Mikserda saryog', shakar kukuni va matcha pastasini ko'pirtirib yashil krem tayyorlang.\"}, {\"text\": \"Sovigan pechenyelarning chuqurchasiga matcha kremini solib chiqib torting.\"}]", "is_published": true}, {"title": "Pishloqli mini-Pirojkalar", "category": "Nonushta va Pishiriqlar", "cook_time_minutes": 50, "difficulty": "o'rtacha", "description": "Qarsildoq uvalanuvchan xamir konvertlari ichida motsarella, feta pishlog'i va ukropli issiq pishloqli mini-pirojkalar.", "ingredients": "[{\"name\": \"Xamir uchun:\\\\n310 g un\"}, {\"name\": \"2 choy qoshiq tuz\"}, {\"name\": \"225 g muzlatilgan saryog'\"}, {\"name\": \"180 ml muzday suv\\\\nIchlik uchun:\\\\n2 dona tuxum\"}, {\"name\": \"115 g feta pishlog'i (yoki brynza)\"}, {\"name\": \"170 g motsarella pishlog'i (qirilgan)\"}, {\"name\": \"3 osh qoshiq ukrop\"}, {\"name\": \"murch va tuz\"}]", "steps": "[{\"text\": \"Idishda un va tuzni aralashtiring. Muzlatilgan saryog'ni qirg'ichdan unli idishga chiqarib, barmoqlar bilan ezib, uvoq holiga keltiring. Muzday suv quyib xamir holiga keltiring va 1 soat muzlatgichda tindiring.\"}, {\"text\": \"Idishda tuxumlarni ko'pirtiring. Yarmini chetga suring. Qolgan tuxumga feta pishlog'ini ezib soling, motsarella, ukrop, murch va tuz qo'shib aralashtiring.\"}, {\"text\": \"Pechni 175°C ga qizdiring. Xamirni ikkiga bo'lib, unlangan stolda to'rtburchak qilib yoying. 16 ta kvadrat bo'lakka bo'ling.\"}, {\"text\": \"Kvadratlar chetiga ko'pirtirilgan tuxum surtib, o'rtasiga pishloqli ichlikdan soling. Uchburchak yoki to'rtburchak qilib buking va sanchqi bilan chetlarini bosing.\"}, {\"text\": \"Ustiga tuxum surtib, pichoq bilan 3 ta kichik kesik qiling. Pergamentli listda 175°C pechda 30–35 daqiqa tillarang bo'lguncha pishiring.\"}]", "is_published": true}];

const LIFEHACKS = [{"title": "Go'shtni tishda chaynaladigan pambiqdek yumshoq qilish", "category": "Pishirish asoslari", "content": "**Tavsif:** Pishirish sodasi (baking soda) yordamida mol va qo'y go'shtini sersuv va yumshoq qilish siri.\n\n**📝 Qo'llash tartibi:**\n1. 450 gramm (1 funt) to'g'ralgan mol yoki qo'y go'shtiga 1 choy qoshiq pishirish sodasi (baking soda) sepib aralashtiring.\n2. Muzlatgichda 30-40 daqiqa qoldiring. Soda go'sht yuzasidagi pH darajasini oshirib, oqsillarning torayib suvni chiqarib yuborishiga yo'l qo'ymaydi.\n3. Pishirishdan oldin go'shtni sovuq suvda yaxshilab yuvib tashlang.\n4. Qog'oz sochiqda quritib olib, odatdagidek pishiring.", "is_published": true}, {"title": "Tova va qozonga ovqat yopishmasligi siri (Leidenfrost effekti)", "category": "Oshxona sirlari", "content": "**Tavsif:** Quruq tovani yaxshi qizdirish va sovuq yog' quyish orqali tabiiy yopishmaydigan qatlam hosil qilish.\n\n**📝 Qo'llash tartibi:**\n1. Qovurishdan oldin tova yoki qozonni quruq holida yaxshilab qizdirib oling.\n2. Tova yetarlicha qiziganini bilish uchun bir-ikki tomchi suv tomizib ko'ring: agar suv bug'lanib ketmay, sharcha bo'lib dumalab 'raqsga tushsa', tova tayyor.\n3. Shundan keyin issiq tovaga sovuq yog' quying.\n4. Yog' metalldagi mikroskopik g'ovaklarni to'ldirib, ovqat yopishmaydigan tabiiy qatlam hosil qiladi.", "is_published": true}, {"title": "Nonni xolodilnikda saqlamang (U yerda non tez qotadi)", "category": "Mahsulotlarni saqlash", "content": "**Tavsif:** Kraxmal retrogradatsiyasi va nonni to'g'ri saqlash hamda qayta yumshatish usuli.\n\n**📝 Qo'llash tartibi:**\n1. Nonni hech qachon xolodilnikning oddiy javoniga qo'ymang (0°C dan 4°C gacha kraxmal molekulalari eng tez kristallashib non qotadi).\n2. Nonni xona haroratida saqlang yoki uzoq muddatga muzxonaga (-18°C) qo'ying.\n3. Qotgan nonni pechda yoki tosterda biroz isitsangiz, kraxmal vaqtincha yumshab, non yana yangidek bo meva bo'ladi.", "is_published": true}, {"title": "Qozonda sochma (dona-dona) palov pishirish siri", "category": "Oshxona sirlari", "content": "**Tavsif:** Guruch ezilib bo'tqa bo'lib ketmasligi uchun zirvak va bug'da damlash siri.\n\n**📝 Qo'llash tartibi:**\n1. Zirvak tayyor bo'lgach, guruchni ustidan tekis solib, mutlaqo aralashtirmaslik kerak.\n2. Guruch suvni tortib bo'lgach, uni o'rtaga tepalik qilib to'plang va tayoqcha bilan teshiklar oching.\n3. Qopqog'ini zich yoping. Bu usul bug'ning bir maromda aylanishini ta'minlab, guruchni dona-dona va havodor qiladi.", "is_published": true}, {"title": "Paxta yoki o'simlik yog'idagi yoqimsiz hidni yo'qotish", "category": "Oshxona sirlari", "content": "**Tavsif:** Qizigan yog'ga piyoz solib qovurish orqali yog'ni tabiiy uglerod filtri bilan tozalash.\n\n**📝 Qo'llash tartibi:**\n1. Qozonga yog' solib qizdirayotganda bitta tozalangan butun piyozni soling.\n2. Piyozni qorayguncha qovurib olib tashlang.\n3. Qovurilgan piyoz tabiiy uglerod filtri vazifasini bajarib, yog'dagi yoqimsiz hidlarni va uchuvchi moddalarni o'ziga tortib oladi.", "is_published": true}, {"title": "Uy sharoitida 'Buttermilk' (Sariyog' suti) o'rinbosarini qilish", "category": "Tezkor usullar", "content": "**Tavsif:** Sutga limon suvi yoki sirka qo'shib pishiriqlar uchun yumshoq ivigan sut tayyorlash.\n\n**📝 Qo'llash tartibi:**\n1. 1 stakan oddiy sutga 1 osh qoshiq limon sharbati yoki oq sirka qo'shing.\n2. Bir necha daqiqa kuting. Sut ivib, pishiriqlarni g'ovak va yumshoq qiluvchi ajoyib buttermilkka aylanadi.\n3. Agar sut bo'lmasa, oddiy qatiq yoki kefir ishlatish ham mukammal natija beradi.", "is_published": true}, {"title": "Xamirga tuxum yetmay qolganda ishlatiladigan layfhak", "category": "Masalliqlarni tejash", "content": "**Tavsif:** Zig'ir/chia urug'i, olma pyuresi, ezilgan banan yoki mayonez bilan tuxumni almashtirish.\n\n**📝 Qo'llash tartibi:**\n1. 1 dona tuxum o'rniga: 1 osh qoshiq maydalangan zig'ir urug'i (flaxseed) yoki chia urug'ini 3 osh qoshiq suv bilan aralashtirib, 5 daqiqa dindiring.\n2. Urug'dagi yelimsimon modda tuxum kabi xamirni mahkam ushlab turadi.\n3. Shuningdek, 1/4 stakan olma pyuresi, ezilgan banan yoki 1 osh qoshiq mayonez ham xamirga yumshoqlik va namlik beradi.", "is_published": true}, {"title": "Pishiriqlar o'xshashi uchun unni stakanda emas, tarozida tortish", "category": "Pishirish asoslari", "content": "**Tavsif:** Pishiriqlar har doim mukammal chiqishi uchun un zichligi va o'lchov siri (1 stakan = 120g).\n\n**📝 Qo'llash tartibi:**\n1. Unni stakan bilan o'lchaganda zichligiga qarab 1 stakan un 110 grammdan 165 grammgacha farq qilishi mumkin.\n2. Pishiriqlar har doim bir xil va mukammal chiqishi uchun unni oshxona tarozisida tortish tavsiya etiladi.\n3. Retseptlarda 1 stakan un deganda odatda 120 gramm nazarda tutiladi.", "is_published": true}, {"title": "Sarimsoqli sous (Toum) achchiq va taxir bo'lib qolmasligi siri", "category": "Oshxona sirlari", "content": "**Tavsif:** Sarimsoq murtagini olib tashlash va sovuq masalliqlardan foydalanish siri.\n\n**📝 Qo'llash tartibi:**\n1. Sarimsoq pallalarining o'rtasidagi yashil murtagini olib tashlang. Aynan shu murtak sousga achchiq va taxir ta'm beradi.\n2. Blender tishlari qizib ketib sous ajralib ketmasligi uchun har doim sovuq masalliqlardan va sovuq idishdan foydalaning.", "is_published": true}, {"title": "Kunjut pastasi (Tahini) ivib, quyulib qolmasligi uchun iliq suv siri", "category": "Oshxona sirlari", "content": "**Tavsif:** 32°C iliq suv va limon sharbati yordamida silliq tahini sousini tayyorlash.\n\n**📝 Qo'llash tartibi:**\n1. Muzdek suv quyish xatodir; sovuq suv kunjut yog'ini qotirib, sousni keshtalab qo'yadi.\n2. Buning o'rniga 32°C atrofidagi iliq suv va limon sharbatidan foydalaning.\n3. Tuzni aralashtirish jarayonida emas, sous tayyor bo'lgandan keyin qo'shsangiz, tarkibi ajralib ketmaydi.", "is_published": true}, {"title": "Professional oshpazlik sirlari (1-qism)", "category": "Oshxona sirlari", "content": "**Tavsif:** Ziravorlarni qizdirib olish, Parmezan po'stlog'i, sousni sovuq sariyog' bilan yakunlash hamda limon suvi bilan tetiklashtirish.\n\n**📝 Qo'llash tartibi:**\n1. Ziravorlarni qizdirib olish: Ziravorlarni tuyish yoki taomga solishdan oldin quruq tovada biroz qizdirilsa, ularning efir yog'lari to'liq ochiladi.\n2. Parmezan po'stlog'ini ishlatish: Parmezan (yoki qattiq pishloq) po'stlog'ini sho'rva va dimlamalarga solib pishirilsa, taomga chuqur va boy ta'm bag'ishlaydi.\n3. Sousni sovuq sariyog' bilan yakunlash: Sous pishishi oxirida olovdan olinadi va unga sovuq sariyog' solib tez-tez aralashtirilsa, yaltiroq va silliq bo'ladi.\n4. Nordonlik bilan taomni tetiklashtirish: Taom pishishi oxirida ozgina limon suvi yoki sirka tomizilsa, ta'm tiniqlashadi va yog'liligi kesiladi.", "is_published": true}, {"title": "Professional oshpazlik sirlari (2-qism)", "category": "Oshxona sirlari", "content": "**Tavsif:** Makaronni yuvmaslik, go'shtni yupqa kesish, qiymani tatib ko'rish, Roux va kotlet o'rtasini botiq qilish.\n\n**📝 Qo'llash tartibi:**\n1. Makaronni suvda yuvmaslik: Pishgan makaron yuzasidagi kraxmal sousning makaronga yaxshi yopishishiga yordam beradi.\n2. Go'shtni biroz muzlatib kesish: Go'shtni yupqa kesish uchun pichoq bilan kesishdan oldin muzlatgichning muzxonasida 20-30 daqiqa ushlab turing.\n3. Qiymani avval tatib ko'rish: Kotlet qiymasining kichik bir bo'lagini tovada qovurib, tuzi va ziravorini to'g'rilab oling.\n4. Roux va Sabzavotlarni blanching qilish: Un va sariyog'ni qovurib roux tayyorlab qo'ying; sabzavotlar yorqin rangi saqlanishi uchun qaynoq suvdan so'ng muzli suvga soling.\n5. Kotlet o'rtasini botiq qilish: Gamburger kotletining o'rtasini barmog'ingiz bilan botiq qilsangiz, bir xil yassi pishadi.", "is_published": true}, {"title": "Mahsulotlarni saqlash layfhaklari", "category": "Mahsulotlarni saqlash", "content": "**Tavsif:** Bulyon uchun paket yig'ish, ko'katlarni guldasta kabi va nam sochiqda uzoq saqlash.\n\n**📝 Qo'llash tartibi:**\n1. Bulyon uchun paket: Sabzavot po'choqlari, poyalari va suyaklarni muzlatgich paketiga yig'ib boring va mazali bulyon qaynatib oling.\n2. Ko'katlarni guldasta kabi saqlash: Rayhon, kashnich, petrushkalarni poyasi bilan suvli stakanga solib saqlasangiz uzoq vaqt yangidek turadi.\n3. Nam sochiq usuli: Ko'katlarni biroz namlangan qog'oz sochiqqa o'rab muzlatgichga qo'yish so'lishining oldini oladi.\n4. Sana qo'yish: Muzlatgichga qo'yiladigan barcha idish va paketlarga tayyorlangan sanasini yozib qo'ying.", "is_published": true}, {"title": "Ishni yengillashtiruvchi tezkor usullar", "category": "Tezkor usullar", "content": "**Tavsif:** Archilgan sarimsoq, tayyor souslarni boyitish, protivenda pishirish va partiya bilan issiq ushlash.\n\n**📝 Qo'llash tartibi:**\n1. Archilgan sarimsoq: Pishiriladigan taomlar uchun oldindan archib qo'yilgan sarimsoqdan foydalanish vaqtni tejaydi.\n2. Tayyor souslarni boyitish: Do'kondan olingan tayyor souslarga yangi ko'katlar, sariyog' yoki sarimsoq qo'shib ta'mini sezilarli yaxshilang.\n3. Protivenda pishirish: Go'sht va sabzavotlarni bitta protivenga terib duxovkada pishirish idish-tovoq yuvishni kamaytiradi.\n4. Partiya bilan pishirishda issiq ushlash: Katta hajmda kotlet yoki steyk qovurayotganda, pishganlarini duxovkada 120°C haroratda sersuv va issiq ushlang.", "is_published": true}, {"title": "Masalliqlarni tejash va qayta ishlatish", "category": "Masalliqlarni tejash", "content": "**Tavsif:** So'ligan ko'katlarni tiriltirish, Akvafaba (noxat suvi), Feta pishlog'i suvi va Sitrus po'stlog'i.\n\n**📝 Qo'llash tartibi:**\n1. So'ligan ko'katlarni tiriltirish: So'lib qolgan ko'katlarni muzli suvga 10-15 daqiqa solib qo'ysangiz qayta qarsillama va tetik holatga keladi.\n2. Akvafaba (Aquafaba): Konservalangan noxat suvini tuxum oqi o'rnida ko'pirtirib, pishiriq va bezaklarda ishlatishingiz mumkin.\n3. Feta pishlog'i suvi: Feta yoki brynza pishlog'i sho'r suvini to'kib tashlamay, makaron uchun sous tayyorlashda ishlatishingiz mumkin.\n4. Sitrus po'stlog'i (Zest): Limon yoki apelsin sharbatini siqishdan oldin, uning xushbo'y po'stlog'ini qirib muzlatib qo'ying.", "is_published": true}, {"title": "Asosiy pishirish texnikalari (1-qism)", "category": "Pishirish asoslari", "content": "**Tavsif:** Sautéing (Tez qovurish), Boiling (Kuchli qaynatish) va Simmering (Sekin qaynatish) qoidalari.\n\n**📝 Qo'llash tartibi:**\n1. Sautéing (Tez qovurish): Tova va yog'ni oldindan yaxshi qizdiring. Tovaga bir vaqtda juda ko'p masalliq solmang (suv chiqarib dimlanib qolmasligi uchun).\n2. Boiling (Kuchli qaynatish - 100°C): Makaron (pasta) pishirishda suv shiddatli qaynab turishi kerak. Sabzavot va nozik masalliqlar uchun esa sekinroq qaynash ma'qul.\n3. Simmering (Muntazam sekin qaynatish - 82-93°C): Suv yuzasida pufakchalar sekin qalqib chiqadi. Sho'rva, dimlama va quyuq souslarni pishirish uchun eng maqbul usul.", "is_published": true}, {"title": "Suyuqlikda dimlash va Pechda pishirish", "category": "Pishirish asoslari", "content": "**Tavsif:** Braising (Sekin dimlash), Roasting (Duxovka) va Grilling (Grill): Qattiq go'sht va sabzavotlar siri.\n\n**📝 Qo'llash tartibi:**\n1. Braising (Suyuqlikda sekin dimlash): Go'shtni avval yuqori olovda qizartirib oling, so'ngra ozgina bulyon quyib, 135-160°C da 2-4 soat past haroratda sekin pishiring.\n2. Roasting (Duxovkada pishirish - 160-230°C): Yuqori harorat mahsulot yuzasida qarsillama qobiq hosil qiladi, pastroq harorat ichigacha bir xil pishiradi.\n3. Grilling (Grillda pishirish): Grill panjarasi oldindan yaxshilab qizdiriladi. Yupqa go'shtlar tik issiqlikda, qalin bo'laklar esa yonlama issiqlikda pishiriladi.", "is_published": true}, {"title": "Bug'da va yog'da pishirish texnikalari", "category": "Pishirish asoslari", "content": "**Tavsif:** Steaming (Bug'), Poaching (Iliq suv) va Deep Frying (Mo'l yog'): Vitaminlarni saqlash va qovurish.\n\n**📝 Qo'llash tartibi:**\n1. Steaming (Bug'da pishirish): Masalliqni suvga botirmasdan bug' issiqligida pishirish. Vitamin, shira va natural ta'mni maksimal saqlab qoladi.\n2. Poaching (70-82°C iliq suvda pishirish): Suv qaynamaydi va pufak hosil qilmaydi. Tuxum (pashot), baliq va nozik mevalar uchun qo'llaniladi.\n3. Deep Frying (Mo'l yog'da qovurish - 175-190°C): Yog' haroratini nazorat qiling, masalliqni birdaniga to'ldirmang. Pishgach yog'i oqishi uchun sim panjaraga oling.", "is_published": true}, {"title": "Ta'm qatlamlarini bosqichma-bosqich hosil qilish", "category": "Pishirish asoslari", "content": "**Tavsif:** Aromatiklar, Bloom (ziravorlarni qizdirish), Deglazing hamda taomga yakuniy nordonlik va ko'kat berish.\n\n**📝 Qo'llash tartibi:**\n1. Aromatiklar (Sabzavotli asos): Avval piyoz, sarimsoq, zanjabil va seldereyni yog'da yengil qovurib oling.\n2. Ziravorlarni qizdirish (Bloom): Ziravorlarni issiq yog'ga solib, ularning efir yog'lari va xushbo'y hidini chiqarib oling.\n3. Tova tubini eritish (Deglazing): Tova tubiga yopishib qolgan mazali qoldiqlarni (fond) ozgina bulyon yoki sharbat solib eritib, sousga aylantiring.\n4. Yakuniy urg'u: Taom pishishi oxirida limon suvi yoki sirka kabi nordonlik hamda yangi uzilgan ko'katlar qo'shing.", "is_published": true}, {"title": "Pishirish jarayonida ta'm berish sirlari", "category": "Pishirish asoslari", "content": "**Tavsif:** Tuzdan to'g'ri foydalanish, Kislota va Yog' balansi hamda Umami ta'm chuqurligi.\n\n**📝 Qo'llash tartibi:**\n1. Tuz: Eng muhim ziravor. Uni faqat pishirish oxirida emas, balki har bir bosqichda oz-ozdan solib borish kerak.\n2. Doimiy tatib ko'rish: Pishirish jarayonida taomni tez-tez tatib ko'ring va ta'm muvozanatini tekshiring.\n3. Kislota va Yog': Nordonlik (limon, sirka) taomga tetiklik beradi va og'ir yog'lilikni kesadi; yog' esa ta'mni og'izda yaxshi tarqatuvchi vositadir.\n4. Umami: Soya sousi, qo'ziqorin, pomidor va Parmezan pishlog'i taomga chuqurlik va to'yingan ta'm bag'ishlaydi.", "is_published": true}, {"title": "Mise en Place (Pishirish oldi tayyorgarligi)", "category": "Pishirish asoslari", "content": "**Tavsif:** Professional oshpazlar intizomi va oshxona ish unumdorligi (Workflow).\n\n**📝 Qo'llash tartibi:**\n1. Mise en Place ('Hamma narsa o'z o'rnida'): Retseptni to'liq o'qing, barcha masalliqlarni yuvib, archib va o'lchab alohida idishlarga ajratib oling.\n2. Ish yo'nalishi (Workflow): Chapdan o'ngga qarab tashkillashtiriladi: Masalliqni qabul qilish -> Tayyorlash -> Pishirish -> Suzish -> Tortish.\n3. Xavfsizlik va tozalik: Xom go'sht ishlanadigan joyni sabzavotlar joyidan ayri tuting hamda pishirish davomida ish joyini tozalab boring.", "is_published": true}, {"title": "Murakkab professional oshpazlik texnikalari", "category": "Pishirish asoslari", "content": "**Tavsif:** Sous Vide (Vakuum), Confit (Yog'da sekin) va Silliq tova souslari tayyorlash.\n\n**📝 Qo'llash tartibi:**\n1. Sous Vide (Vakuumda pishirish): Masalliqni vakuumli xaltada harorati aniq belgilangan issiq suvli maxsus apparatda pishirish. Har bir nuqtasigacha bir xil pishadi.\n2. Confit (Yog'da sekin pishirish): Masalliqni juda past haroratda (90-120°C) o'z yog'iga to'liq botirgan holda, soatlab yumshaguncha pishirish.\n3. Deglazing va Tova souslari: Tova tubiga yopishgan ta'mlarni eritib, sekin qaynatib quyultirish va sovuq saryog' solib yaltiroq, silliq sous hosil qilish.", "is_published": true}, {"title": "Sabzavotlardan atirgul qilish", "category": "Karving va Bezak", "content": "**Tavsif:** Sabzi va bodring bo'lakchalaridan bayramona dasturxon uchun go'zal atirgul shaklini yasash siri.\n\n**📝 Qo'llash tartibi:**\n1. Bodring va sabzini pichoq bilan juda yupqa doiracha qilib to'g'rang.\n2. Birinchi bo'lakni mahkam o'rang.\n3. Keyingi bo'laklarni atrofidan barg ko'rinishida ketma-ket joylashtiring.\n4. Zubochistka bilan ostidan mahkamlab dasturxonga qo'ying.", "is_published": true}, {"title": "Qog'ozdan qayiq yasash", "category": "Bolalar uchun", "content": "**Tavsif:** Farzandingiz bilan birgalikda 3 daqiqada qiziqarli rangli qog'ozdan suzuvchi qayiqcha yasash.\n\n**📝 Qo'llash tartibi:**\n1. A4 qog'ozni teng ikkiga taxlang.\n2. Yuqori burchaklarini markazga qarab buking.\n3. Paski chetlarini yuqoriga qayring va uchburchak hosil qiling.\n4. Markazidan ochib kvadrat shakliga keltiring va qayiqni yoying!", "is_published": true}, {"title": "Xonani tezda tartiblash usullari", "category": "Uy-ro'zg'or va Xavfsizlik", "content": "**Tavsif:** Bolalar o'yinchoqlarini 5 daqiqada o'yin ko'rinishida yig'ish usullari va qutilar tizimi.\n\n**📝 Qo'llash tartibi:**\n1. Rangli 3 ta savat tayyorlang: yumshoq o'yinchoqlar, konstruktorlar va kitoblar uchun.\n2. Taymerni 5 daqiqaga qo'ying va kim tez yig'ish o'yinini o'ynang.\n3. Bajarilgach farzandingizni maqtang va barmoqcha rasm bering.", "is_published": true}, {"title": "Kitobni muqovasini yasash", "category": "boshqa", "content": "**Tavsif:** Maktab darsliklari va ertak kitoblarini qiziqarli rangli muqova bilan asrash.\n\n**📝 Qo'llash tartibi:**\n1. Qalin qog'ozni kitob hajmidan biroz kattaroq qilib kesing.\n2. Kitob chetlarini ichkariga buking va skotch bilan mahkamlang.\n3. Farzandingiz stikerlar va qalamlar bilan bezatishiga imkon bering.", "is_published": true}, {"title": "Qattiq va yumshoq ko'katlarni solish vaqtini ajrating", "category": "Pishirish asoslari", "content": "**Tavsif:** Rozmarin, timyan va lavr yaprog'i kabi qattiq poyali ko'katlarning xushbo'yligi issiqqa chidamli bo'lgani uchun ularni pishirishning boshida solish kerak. Kashnich, petrushka, rayhon va yalpiz kabi yumshoq ko'katlarning hidi esa issiqda yo'qoladi, shuning uchun ularni faqat pishish oxirida yoki taomni suzishda qo'shing.\n\n**📝 Qo'llash tartibi:**\n1. Qattiq poyali ko'katlar (rozmarin, timyan, lavr)ni taom qaynashning boshida yoki dimlashda qo'shing.\n2. Yumshoq ko'katlar (kashnich, petrushka, rayhon, yalpiz)ni to'g'rab, olovdan olishdan 1-2 daqiqa oldin yoki suzish paytida soling.\n3. Bu usul taomning barcha efir yog'lari va xushbo'y hidini 100% saqlab qoladi.\n\n**✨ Foydali jihatlari:**\n- Efir yog'lari yo'qolmaydi\n- Ko'katlar rangini va vitaminlarini saqlaydi", "is_published": true}, {"title": "Qovurilgan go'shtni kesishdan oldin 3–5 daqiqa \"dam oldiring\"", "category": "Pishirish asoslari", "content": "**Tavsif:** Go'sht qovurilib yoki duxovkadan olingach, uni darhol kesmang. Biroz kutsangiz, ichidagi qaynoq sharbat (suv) go'sht tolalari bo'ylab qayta teng taqsimlanadi va kesganda taxtaga oqib ketmasdan, go'shtning o'zida saqlanib qoladi.\n\n**📝 Qo'llash tartibi:**\n1. Go'shtni olovdan yoki duxovkadan olgach, taxtaga qo'yib ustiga zarvaraq (folga)ni bo'shroq yopib qo'ying.\n2. 3–5 daqiqa (yirik bo'laklar uchun 10 daqiqa) kutib turing.\n3. Toblangan sharbat tolalarga singib, go'sht kesilganda suvli va yumshoq bo'ladi.\n\n**✨ Foydali jihatlari:**\n- Go'sht suvli bo'lib qoladi\n- Sharbat taxtaga oqib ketmaydi", "is_published": true}, {"title": "Muzday tuxumni tezda xona haroratiga keltirish", "category": "Tezkor usullar", "content": "**Tavsif:** Pishiriqlar uchun xona haroratidagi tuxum kerak bo'lsa-yu, tuxum muzlatgichda turgan bo'lsa, ularni issiqroq (iliq) suvli idishga 10 daqiqaga solib qo'ying.\n\n**📝 Qo'llash tartibi:**\n1. Kichik chuqur idishga iliq (40°C atrofida, qaynoq emas) suv quying.\n2. Muzlatgichdan olingan tuxumlarni ehtiyotkorlik bilan iliq suvga bosing.\n3. 10 daqiqaga qoldiring — tuxumlar xamir ko'pirtirish uchun ideal xona haroratiga keladi.\n\n**✨ Foydali jihatlari:**\n- Biskvit va piroglar yaxshi ko'tariladi\n- 10 daqiqada tezkor natija", "is_published": true}, {"title": "Qovurishdan oldin go'sht va sabzavotlar yuzasini qug'oz sochiqda quritish", "category": "Pishirish asoslari", "content": "**Tavsif:** Masalliqlar yuzasidagi namlik tovaga tushishi bilan haroratni darhol 60°C gacha tushirib yuboradi. Natijada ovqat qizarmaydi, balki o'z suvida dimlanib (qaynab) qoladi.\n\n**📝 Qo'llash tartibi:**\n1. Go'sht yoki to'g'ralgan sabzavotlarni qovurishdan oldin qog'oz sochiq bilan artib, yuzasidagi namlikni shimdirib oling.\n2. Tovadagi yog'ni yaxshilab qizdiring.\n3. Quruq yuzali masalliq darhol qizarib, chiroyli tillarang qatlam (Mayyar reaksiyasi) hosil qiladi.\n\n**✨ Foydali jihatlari:**\n- Tillarang qarsillama qatlam\n- Tova harorati tushib ketmaydi", "is_published": true}, {"title": "Qovurilgan guruch va qovurma uchun kechagi guruchdan foydalaning", "category": "Oshxona sirlari", "content": "**Tavsif:** Kechasi muzlatgichda turgan guruch tarkibidagi namlik kamayadi (18% dan 12% gacha tushadi). Shuning uchun kechagi guruch qovurilganda bir-biriga yopishib bo'tqa bo'lmay, dona-dona bo'lib chiqadi.\n\n**📝 Qo'llash tartibi:**\n1. Pishgan guruchni xona haroratida sovutib, havosi o'tadigan idishda kechasi muzlatgichga qo'ying.\n2. Ertasi kuni guruch donalari bir-biridan ajraladigan quruq holatga keladi.\n3. Yuqori olovda sabzavot va go'sht bilan qovurganda dona-dona va mazali chiqadi.\n\n**✨ Foydali jihatlari:**\n- Guruch bo'tqa bo'lib ketmaydi\n- Restaurant uslubidagi dona-dona qovurma", "is_published": true}, {"title": "Sarimsoqpiyozni kuydirib qo'ymaslik siri", "category": "Oshxona sirlari", "content": "**Tavsif:** Sarimsoq tarkibida shakar ko'p bo'lgani uchun baland olovda juda tez kuyib, taxir ta'm beradi. Qovurmalarda sarimsoqni eng oxirida yoki suvli sabzavotlar solingandan keyin qo'shish kerak.\n\n**📝 Qo'llash tartibi:**\n1. Piyoz va go'shtni qovurib bo'lgach, olovni biroz pasaytiring.\n2. Sarimsoqni to'g'rab yoki ezib, pishish oxiriga 1-2 daqiqa qolganda qo'shing.\n3. Yoki sarimsoqni tomat/sabzavotlar suv chiqargandan keyin soling.\n\n**✨ Foydali jihatlari:**\n- Achchiq/taxir ta'm bo'lmaydi\n- Sarimsoqning xushbo'yligi to'liq ochiladi", "is_published": true}, {"title": "Eritilayotgan shokoladga bir tomchi ham suv tushirmang", "category": "Pishirish asoslari", "content": "**Tavsif:** Shokoladni eritayotganda ichiga hatto bir tomchi suv yoki idish bug'i tushsa ham, u darhol qotib, quyqa (keshtalangan) bo'lib qoladi va qayta erimaydi.\n\n**📝 Qo'llash tartibi:**\n1. Suv bug'i idishining osti shokolad idishiga tegmasligiga va idishlar quruqligiga ishonch hosil qiling.\n2. Shokoladni eritayotganda qopqoq yopmang (bug' suvga aylanib tushmasligi uchun).\n3. Agar tasodifan suv tushsa, 1 osh qoshiq issiq sariyog' yoki qaymoq qo'shib sous holatiga keltiring.\n\n**✨ Foydali jihatlari:**\n- Silliq yaltiroq shokolad\n- Quyqa bo'lib qotib qolmaydi", "is_published": true}, {"title": "Qiymali kabob sixdan tushib ketmasligi uchun sabzavot suvini siqing", "category": "Oshxona sirlari", "content": "**Tavsif:** Qiymaga qo'shiladigan bulg'or qalampiri yoki piyozni maydalagach, suvini doka yoki suzgichda yaxshilab siqib tashlash kerak. Ortiqcha suv pishishda bug' berib, go'sht oqsillari (miozin) yopishqoqligini yo'qotadi va kabob cho'g'ga tushib ketadi.\n\n**📝 Qo'llash tartibi:**\n1. Piyoz va bulg'or qalampirini blender yoki qirg'ichdan chiqargach, dokaga solib suvini oxirigacha siqib tashlang.\n2. Faqat quruq sabzavot mag'zini qiymaga qo'shib, go'shtni 10 daqiqa yaxshilab urib qoring.\n3. Sixga tortgach, kabob cho'g'da oqmay, tekis pishadi.\n\n**✨ Foydali jihatlari:**\n- Sixdan tushmaydigan mahkam qiymali kabob\n- Glavniy chef siri", "is_published": true}, {"title": "Tovadagi yog'ga olov ketganda (Grease fire) hech qachon suv quymang", "category": "Uy-ro'zg'or va Xavfsizlik", "content": "**Tavsif:** Yonayotgan yog'ga suv quyilsa, suv darhol bug'ga aylanib, yonayotgan yog'ni butun oshxonaga sachratib yuboradi. Olovni o'chirish uchun tovani metall qopqoq bilan yopib kislorodni bosing yoki ustiga pishirish sodasi sepib tashlang.\n\n**📝 Qo'llash tartibi:**\n1. Zarur qoida: Olovli yog'ga HECH QACHON suv quymang!\n2. Darhol olovni (gaz/plitani) o'chiring.\n3. Tovaning ustini metall qopqoq yoki patnis bilan to'liq yoping (kislorod kesilib olov o'chadi).\n4. Yoki ustiga ko'p miqdorda pishirish sodasi (baking soda) sepib tashlang.\n\n**✨ Foydali jihatlari:**\n- Oshxona xavfsizligi\n- Yong'in xavfidan saqlanish", "is_published": true}];

export default async function handler(req: VercelRequest, res: VercelResponse) {
  try {
    const isReset = req.query.reset === "1" || req.query.reset === "true";
    if (isReset) {
      await supabaseFetch("DELETE", "recipes", { id: "gt.0" });
      await supabaseFetch("DELETE", "lifehacks", { id: "gt.0" });
    }

    let insertedRecipes = 0;
    for (let i = 0; i < RECIPES.length; i += 20) {
      const batch = RECIPES.slice(i, i + 20);
      await supabaseFetch("POST", "recipes", undefined, batch, "return=minimal");
      insertedRecipes += batch.length;
    }

    let insertedLifehacks = 0;
    for (let i = 0; i < LIFEHACKS.length; i += 20) {
      const batch = LIFEHACKS.slice(i, i + 20);
      await supabaseFetch("POST", "lifehacks", undefined, batch, "return=minimal");
      insertedLifehacks += batch.length;
    }

    return res.status(200).json({
      ok: true,
      message: "Barcha retsept va layfhaklar Supabase ga muvaffaqiyatli saqlandi!",
      recipesCount: insertedRecipes,
      lifehacksCount: insertedLifehacks,
    });
  } catch (error: any) {
    return res.status(500).json({
      ok: false,
      error: error?.message ?? "Server error",
    });
  }
}
